    // Flat ring (annulus)
    difference() {
        cylinder(d = ring_outer_d, h = ring_thickness, $fn = 128);
        translate([0, 0, ring_top_z - overlap])
            cylinder(d = ring_inner_d, h = ring_thickness + 2 * overlap, $fn = 128);
    }

    // Three legs, axes on the specified circle
    for (i = [0 : leg_count - 1]) {
        rotate([0, 0, leg_start_angle + i * leg_angle])
            translate([leg_circle_d / 2, 0, ring_top_z - overlap])
                cylinder(d = leg_d, h = ring_thickness + 2 * overlap, $fn = 64);
    }
