```openscad
// Circuit board spacer with sunk socket-head screw
// Print orientation: base on bed (z = 0), counterbore opens at top

// ---------- Parameters ----------
spacer_d      = 16;    // cylinder diameter
spacer_h      = 15;    // cylinder height
screw_d       = 3.4;   // through-hole diameter (socket-head screw)
counterbore_d = 6.5;   // counterbore diameter
counterbore_depth = 5; // counterbore depth from top face (z = 10 to 15)
eps           = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    // Main spacer body
    cylinder(d = spacer_d, h = spacer_h);

    // Through-hole for screw
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = spacer_h + 2 * eps);

    // Coaxial counterbore from top face
    translate([0, 0, spacer_h - counterbore_depth])
        cylinder(d = counterbore_d, h = counterbore_depth + eps);
}
```

