// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail builds upward (+Z)

// ---------------- Parameters ----------------
plate_len   = 60;    // base plate length (X)
plate_wid   = 30;    // base plate width (Y)
plate_thk   = 6;     // base plate thickness (Z)

rail_bot_w  = 10;    // dovetail rail width at plate top (z = 6)
rail_top_w  = 14;    // dovetail rail width at top face (z = 11)
rail_h      = 5;     // dovetail rail height (z = 6 to 11)

eps         = 0.5;   // overcut for clean boolean differences
$fn         = 96;    // curve resolution

// Derived: rail slope (Y change per unit Z)
rail_slope  = (rail_top_w - rail_bot_w) / rail_h;   // 0.8 mm/mm

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail, centred on y = 0, running full length along X
    translate([-plate_len/2, -rail_bot_w/2, plate_thk])
        linear_extrude(height = rail_h + eps)
            hull() {
                // Lower edge: rectangle [rail_bot_w x (rail_h + eps)], centred on y = 0
                translate([0, -rail_bot_w/2]) cube([rail_bot_w, rail_h + eps]);

                // Upper edge: trapezoid flaring outward, centred on y = 0
                //   y = +/- (rail_top_w/2 - rail_bot_w/2) at z = rail_h (overcut included)
                translate([0, -(rail_top_w/2 - rail_bot_w/2)])
                    cube([rail_top_w, rail_h + eps]);
            }
