// Door hold-open wedge
// Print orientation: base on XY plane, hypotenuse facing up (+Z)

// ---------- Parameters ----------
wedge_len   = 120;   // wedge length along X (mm)
wedge_wid   = 40;    // wedge width along Y (mm)
wedge_ht    = 25;    // wedge height at thick end (Z, mm)

slot_w      = 6;     // slot width along Y (mm)
slot_len    = 30;    // slot length along X (mm)
slot_x      = 60;    // slot centre X (mm)
slot_y      = 20;    // slot centre Y (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)

$fn = 64;

// ---------- Model ----------
difference() {
    // Wedge body: right triangle in XZ, extruded along Y
    translate([0, 0, 0])
        linear_extrude(wedge_wid)
            polygon([["x = 0", "z = 0"], ["x = 120", "z = 0"], ["x = 0", "z = 25"]]);

    // Vertical slot through the wedge
    translate([slot_x, slot_y, -eps])
        cube([slot_len, slot_w, wedge_ht + 2 * eps]);
}
