// Glass stirring rod rest
// Print orientation: flat on bed, grooves facing up

// ---- Block ----
block_l = 84;      // length along X
block_w = 50;      // width along Y
block_h = 12;      // height along Z

// ---- Grooves ----
groove_n     = 4;    // number of grooves
groove_pitch = 18;   // centre-to-centre spacing along X
groove_w     = 8;    // groove width at top surface
groove_d     = 4;    // groove depth
groove_a     = 45;   // half-angle of V profile (90-degree V)

// ---- Misc ----
eps = 0.5;          // cutter overshoot past top face
$fn = 96;

// Width of groove at depth z below the top surface
function groove_width(z) = groove_w + 2 * z * tan(groove_a);

difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_l/2, -block_w/2, 0])
        cube([block_l, block_w, block_h]);

    // V-shaped grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        x = (i - (groove_n - 1)/2) * groove_pitch;
        translate([x - block_l/2, -block_w/2, block_h - groove_d])
            linear_extrude(height = block_w + 2 * eps)
                polygon([[-groove_w/2, -block_w/2 - eps], [groove_w/2, -block_w/2 - eps],
                         [groove_w/2, block_w/2 + eps], [-groove_w/2, block_w/2 + eps]]);
    }
}
