// ---- Block dimensions ----
block_len   = 65;   // length along X
block_wid   = 30;   // width along Y
block_ht    = 15;   // height along Z

// ---- Groove parameters ----
groove_n     = 4;   // number of V-grooves
groove_pitch = 15;  // centre-to-centre spacing along X
groove_w     = 10;  // groove width at top surface (along X)
groove_d     = 5;   // groove depth from top surface
groove_a     = 90;  // V-profile angle (degrees)

// ---- Derived ----
overcut = 0.5;      // extension of cutters past the top face
x0      = -(groove_n - 1) * groove_pitch / 2;  // first groove centre X

$fn = 96;

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([x0 + i * groove_pitch, -block_wid / 2 - overcut, block_ht - groove_d])
            rotate([0, 90, 0])
                linear_extrude(height = block_wid + 2 * overcut)
                    polygon([[-groove_w / 2, 0], [groove_w / 2, 0],
                              [0, -groove_w / tan(groove_a / 2)],
                              [0, groove_w / tan(groove_a / 2)]]);
    }
}
