```openscad
// Glass stirring rod rest - rectangular block with V-shaped grooves along Y
// Print orientation: base on the bed, grooves open upward (+Z)

// ---------------- Parameters ----------------
block_len    = 96;    // block length along X (mm)
block_wid    = 30;    // block width along Y (mm)
block_ht     = 15;    // block height along Z (mm)

groove_count = 5;     // number of V-shaped grooves
groove_pitch = 18;    // centre-to-centre spacing along X (mm)
groove_wt    = 10;    // groove width at the top surface (mm)
groove_depth = 5;     // groove depth from the top surface (mm)

eps          = 0.5;   // overcut past faces to avoid coplanar surfaces (mm)

$fn = 96;             // curve resolution

// ---------------- Derived ----------------
// For a 90-degree V groove the two faces are at 45 degrees.
// The width narrows by 2*tan(45)*d = 2d over a depth d.
// At the bottom of the groove (depth = groove_depth) the width is:
groove_base_w = groove_wt - 2 * groove_depth;   // 10 - 2*5 = 0 mm (sharp V)

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves running the full width along Y
    for (i = [0 : groove_count - 1]) {
        x_c = (i - (groove_count - 1)/2) * groove_pitch;
        translate([x_c - eps/2, -block_wid/2 - eps/2, block_ht - groove_depth])
            // 90-degree V: two planar faces at 45 degrees, open upward
            linear_extrude(height = block_wid + eps)
                polygon([[-groove_wt/2, 0], [groove_wt/2, 0],
                         [0, block_ht - groove_depth]]);
    }
}
```

```openscad
// Glass stirring rod rest - rectangular block with 5 V-shaped grooves along Y
// Print orientation: base on the bed (z = 0), grooves open upward

// ---------------- Parameters ----------------
block_len   = 96;    // block length along X (mm)
block_wid   = 30;    // block width along Y (mm)
block_ht    = 15;    // block height along Z (mm)

groove_n     = 5;    // number of V-grooves
groove_pitch = 18;   // centre-to-centre spacing along X (mm)
groove_wt    = 10;   // groove width at top surface (mm)
groove_depth = 5;    // groove depth from top surface (mm)

eps          = 0.5;  // overcut past faces to avoid coplanar surfaces (mm)

$fn = 96;

// ---------------- Derived ----------------
// For a 90-degree V, the side walls have a 45-degree slope.
// Extending the groove full depth + eps keeps the overcut at 45 degrees.
groove_ext = groove_depth + eps;

// First groove centre X, then repeat by pitch
groove_x = [i * groove_pitch - (groove_n - 1) * groove_pitch / 2 
            for i in [0 : groove_n - 1]];

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running the full width along Y
    for (x = groove_x)
        translate([x - groove_wt / 2, -block_wid / 2 - eps, groove_ext])
            rotate([0, 90, 0])
                linear_extrude(height = block_wid + 2 * eps)
                    polygon([[-groove_wt / 2, 0], [groove_wt / 2, 0],
                              [0, -groove_ext]]);
}
```

