```openscad
// Hex-nut captive clamping block
// Print orientation: block rests on XY plane at z = 0, builds upward (+Z)

// ---------------- Parameters ----------------
block_x      = 24;    // block length in X (mm)
block_y      = 24;    // block width in Y (mm)
block_z      = 12;    // block height in Z (mm)

through_d    = 5.5;   // vertical through-hole diameter (mm)

hex_af       = 8.2;   // hex pocket size across flats (mm)
hex_depth    = 4.2;   // hex pocket depth from bottom face (mm)

eps          = 0.5;   // cutter overshoot past faces (mm)
$fn          = 96;    // curve resolution

// Derived
hex_r = (hex_af / 2) / cos(30);   // hex circumradius (across corners / 2)

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Central vertical through-hole
    translate([0, 0, -eps])
        cylinder(d = through_d, h = block_z + 2 * eps);

    // Hexagonal pocket cut from the bottom face
    // cylinder with $fn = 6 has vertices on the X axis,
    // so two flats are parallel to the X axis
    translate([0, 0, block_z - hex_depth])
        cylinder(r = hex_r, h = hex_depth + eps, $fn = 6);
}
