// Stepped riser - a solid 3-step staircase, extruded along Y, for setting samples at
// different heights. Print orientation: base on the bed (z = 0), steps climbing in +X.
// Units: mm. No external libraries.

// ---------------- Parameters ----------------
step_count   = 3;    // number of steps
step_length  = 10;   // X-length of each step (also the height gain per step)
first_height = 10;   // height of the first step (at x = 0)
extrusion    = 40;   // Y-length of the staircase (y = 0 to y = 40)
eps          = 0.5;  // overcut so cutting shapes pass beyond faces

// Derived
top_height = first_height + (step_count - 1) * step_length;  // 30 mm
x_end      = step_count * step_length;                       // 30 mm

// ---------------- Model ----------------
difference() {
    // Solid block that covers the full staircase footprint
    translate([0, 0, 0])
        cube([x_end, extrusion, top_height]);

    // Cut out the empty space under the steps, leaving only the stepped solid
    for (i = [0 : step_count - 1]) {
        x0 = i * step_length;
        // Each cut is a slab of the full Y-length and one step's X-length,
        // sitting on the bed and reaching up to the top of the current step.
        translate([x0, 0, 0])
            cube([step_length, extrusion, first_height + i * step_length + eps]);
    }
}
