// Stepped riser - solid staircase of 3 equal steps, print orientation: base on bed,
// profile climbs in +X direction. NOVEL general part.
//

$fn = 64;

// ---- Dimensions (mm) ----
step_count   = 3;     // number of steps
step_length  = 12;    // X length of each step
step_height  = 8;     // height gain of each step over the previous
top_height   = 24;    // height of the top step (check: count*height)
end_x        = 36;    // X position of the top step end (check: count*length)
extrude_y    = 30;    // Y thickness of the extrusion
cut_overlap  = 0.5;   // extra cut length past faces to avoid coplanar surfaces

// Derived
first_height = step_height;              // first step height (same as gain)
x0           = 0;                        // X start of first step

// Each step is a block [x0..x0+length] x [y0..y0+extrude] x [z0..z0+height]
// stacked on the bed (z0 = 0 for the first, z0 = previous top for the rest).
for (i = [0 : step_count - 1]) {
    x0      = i * step_length;
    z0      = i * step_height;
    x1      = x0 + step_length;
    z1      = z0 + step_height;
    y0      = 0;
    y1      = extrude_y;

    difference() {
        translate([x0, y0, z0]) cube([step_length, extrude_y, step_height]);
        // Cut the next step's volume out, through the whole Y span and a bit past
        // the top and side faces so no faces are exactly coplanar.
        translate([x1 - cut_overlap, y0, z1])
            cube([step_length + cut_overlap, extrude_y + 2 * cut_overlap, step_height]);
    }
}
