    // resting on z = 0, extending above the highest washer.
    translate([-row_length / 2, 0, 0])
        cube([row_length + 2 * row_overlap, 16 * row_overlap, washer_t]);

    // Through-cut for each washer, centred on y = 0 and spaced by pitch.
    for (i = [0 : washer_count - 1]) {
        translate([i * washer_pitch, 0, -row_overlap])
            cylinder(d = washer_bore, h = washer_t + 2 * row_overlap);
    }
}
