// Glass stirring rod rest - rectangular block with V-shaped grooves along Y
// Print orientation: base on the bed, grooves open upward (+Z)

// ---------------- Parameters ----------------
block_len   = 99;    // block length along X (mm)
block_wid   = 40;    // block width along Y (mm)
block_ht    = 15;    // block height along Z (mm)

groove_n     = 6;    // number of V-grooves
groove_pitch = 15;   // centre-to-centre spacing along X (mm)
groove_wt    = 8;    // groove width at the top surface (mm)
groove_d     = 4;    // groove depth from the top surface (mm)

eps          = 0.5;  // overcut so cutting shapes pass beyond the top face

$fn = 96;

// ---------------- Derived ----------------
// For a 90-degree V, the two faces are at 45 degrees.
// The width narrows by 2*depth as it goes down, so the opening at the surface
// is 2*(depth + sqrt(depth^2 + (width/2)^2)).
// Solving for depth given a top width gives:
// depth = (width/2) * (sqrt(2) - 1)
groove_depth = (groove_wt / 2) * (sqrt(2) - 1);  // ~2.34 mm (check: 4 mm requested)

// X position of the first groove so the pattern is centred on the origin
groove_x0 = -(groove_n - 1) * groove_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves running the full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([groove_x0 + i * groove_pitch, -block_wid / 2 - eps, block_ht - groove_d])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-groove_wt / 2, -sqrt(groove_d * groove_d + groove_wt / 2 / groove_wt * groove_wt / 2)],
                         [ groove_wt / 2, -sqrt(groove_d * groove_d + groove_wt / 2 / groove_wt * groove_wt / 2)],
                         [ groove_wt / 2,  sqrt(groove_d * groove_d + groove_wt / 2 / groove_wt * groove_wt / 2)],
                         [-groove_wt / 2,  sqrt(groove_d * groove_d + groove_wt / 2 / groove_wt * groove_wt / 2)]]);
    }
}
