// Glass stirring rod rest
// Print orientation: base on bed (z = 0), grooves facing up

// ---------- Parameters ----------
block_len   = 50;    // block length along X (mm)
block_wid   = 30;    // block width along Y (mm)
block_ht    = 12;    // block height along Z (mm)

groove_n     = 3;    // number of V grooves
groove_pitch = 15;   // centre-to-centre spacing along X (mm)
groove_wt    = 8;    // groove width at top surface (mm)
groove_dep   = 4;    // groove depth from top surface (mm)

eps          = 0.5;  // overcut past faces to avoid coplanar faces (mm)

$fn = 96;

// ---------- Derived ----------
// For a 90-degree V groove, the side walls are at 45 degrees.
// Extending the walls up by eps makes the top opening (gt) larger by 2*eps.
// The depth from the top surface is therefore (gt - wt) / 2 = eps.
gt = groove_wt + 2 * eps;

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V grooves running full width along Y, centred along X
    for (i = [0 : groove_n - 1]) {
        x = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x - block_len / 2 - eps, -block_wid / 2 - eps,
                   block_ht - groove_dep])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-eps, -gt / 2], [-eps, gt / 2],
                         [eps, gt / 2], [eps, -gt / 2]]);
    }
}
