    translate([-block_l / 2, -block_w / 2, 0])
        cube([block_l, block_w, block_h]);

    // V-grooves cut full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([groove_x0 + i * groove_pitch - block_l / 2, -block_w / 2 - eps, block_h - groove_d])
            linear_extrude(height = block_w + 2 * eps)
                polygon([[-over, 0], [over, 0], [over - eps * tan(groove_a), -eps],
                         [-over + eps * tan(groove_a), eps]]);
    }
}
