```openscad
// Hex-nut captive clamping block
// Print orientation: block rests on XY plane at z = 0, builds upward (+Z)

// ---------------- Parameters ----------------
block_x      = 24;    // block length along X (mm)
block_y      = 20;    // block width along Y (mm)
block_z      = 12;    // block height along Z (mm)

hole_d       = 3.4;   // vertical through-hole diameter (mm)

hex_af       = 5.6;   // hex pocket size across flats (mm)
hex_depth    = 2.6;   // hex pocket depth from bottom face (mm)

overcut      = 0.5;   // extra length of cutters past faces (mm)
$fn          = 96;    // curve resolution

// Derived
hex_r = (hex_af / 2) / cos(30);   // hex circumradius (across corners / 2)

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Central vertical through-hole
    translate([0, 0, -overcut])
        cylinder(d = hole_d, h = block_z + 2 * overcut);

    // Hexagonal pocket cut from the bottom face
    // cylinder with $fn = 6 has vertices on the X axis,
    // so two flats are parallel to the X axis
    translate([0, 0, block_z - hex_depth])
        cylinder(r = hex_r, h = hex_depth + overcut, $fn = 6);
}
```

