// Split collet - a round tube with axial slots that opens to grip a tube or rod.
// Print orientation: standing on the bed, slots facing up (+Z).
//

// ---- Parameters ----
collet_d      = 24;    // outer diameter of collet
collet_bore   = 18;    // bore diameter (through the wall)
collet_h      = 30;    // total height of collet (z = 0 to z = 30)
slot_w        = 2;     // width of each axial slot
slot_depth    = 12;    // slots run from the top end down to z = 18 (30 - 12)
slot_count    = 3;     // number of slots, evenly spaced
slot_start_x  = 12;    // first slot centred on +X axis (d/2)
eps           = 0.5;   // overcut so cutting faces are not coplanar

$fn = 96;

// ---- Model ----
difference() {
    // Main tube body
    cylinder(d = collet_d, h = collet_h);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = collet_bore, h = collet_h + 2 * eps);

    // Axial slots, cut from the top end down to z = 18
