$fn = 96;                // curve resolution

// ---------------- Model ----------------
difference() {
    // Plate body, centred in X/Y, resting on z = 0
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thickness]);

    // Round hole through the plate at the origin
    translate([0, 0, -cut_extra])
        cylinder(d = hole_diameter, h = plate_thickness + 2 * cut_extra);

    // Keyhole slot: straight segment along +X from the hole, then a rounded end
    slot_length = slot_end_x - slot_width / 2;  // end of straight segment
    union() {
        // Straight slot (overlaps the hole along X, which is fine)
        translate([-slot_width / 2, 0, -cut_extra])
            cube([slot_length + cut_extra, slot_width, plate_thickness + 2 * cut_extra]);

        // Rounded slot end, centred at (slot_end_x, slot_end_y)
        translate([slot_end_x - slot_width / 2, slot_end_y, -cut_extra])
            cylinder(d = slot_width, h = plate_thickness + 2 * cut_extra, $fn = 64);
    }
}
