// Stepped riser - a solid 5-step staircase, extruded along Y, for setting samples at
// different heights. Print orientation: base on the bed (z = 0), steps climbing in +X.
// Units: mm. No external libraries.

// ---------------- Parameters ----------------
step_count   = 5;     // number of steps
step_length  = 15;    // X-length of each step (mm)
step_height  = 10;    // height increment per step (mm)
first_height = 10;    // height of the first step (mm)
top_height   = 50;    // height of the top step (mm)
end_x        = 75;    // X position of the top step end (mm)
extrude_w    = 20;    // Y-width of the staircase (mm)
eps          = 0.5;   // cutter overshoot past faces (mm)

// Derived: X start of each step (x = 0 for the first)
for (i = [0 : step_count - 1])
    step_x[i] = i * step_length;

// ---------------- Model ----------------
difference() {
    // Solid block that covers the full staircase footprint
    translate([min(step_x), 0, 0])
        cube([end_x - min(step_x), extrude_w, top_height]);

    // Cut out the empty space under each step, from the bed up to its top face
    for (i = [0 : step_count - 1]) {
        translate([step_x[i] + eps, 0, 0])
            cube([step_length - 2 * eps, extrude_w, first_height + i * step_height]);
    }
}
