// ---------- Model ----------
difference() {
    // Solid block covering the full staircase envelope
    translate([0, 0, 0])
        cube([end_x, extrude_w, top_height]);

    // Cut out the empty space under each step, pasted through the top face
    for (i = [0 : step_count - 1]) {
        translate([step_x(i), 0, first_height + i * step_height])
            cube([step_length, extrude_w + 2 * eps, step_height + eps]);
