// Display base with bevelled top edges
// Print orientation: flat on XY plane, top face at z = 15

// ---------- Parameters ----------
block_x      = 60;    // block length in X (mm)
block_y      = 40;    // block width in Y (mm)
block_h      = 15;    // block height in Z (mm)

chamfer_w    = 2;     // chamfer width along the edge (mm)
chamfer_angle = 45;   // chamfer angle (degrees)

eps          = 0.5;   // overcut past faces to avoid coplanar surfaces (mm)
$fn          = 64;    // curve resolution

// ---------- Derived ----------
// Because the chamfer is 45 deg, the height lost on each side equals the width
chamfer_h    = chamfer_w * tan(chamfer_angle);
// Top face dimensions after the two chamfers per side
top_x        = block_x - 2 * chamfer_w;
top_y        = block_y - 2 * chamfer_w;
// Vertical sides stop at this height (15 - 2*2 = 11 mm)
side_h       = block_h - 2 * chamfer_h;

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Four top-edge chamfers, each extended above the top face
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x/2 - chamfer_w : -block_x/2,
                   sy > 0 ? block_y/2 - chamfer_w : -block_y/2,
                   block_h - chamfer_h])
            // 45 deg ramp: X and Y both change by the same amount along Z
            translate([chamfer_w, chamfer_w, 0])
                cube([chamfer_w, chamfer_w, chamfer_h + eps]);
    }

    // Bottom edges stay sharp -> no cut here
}
