chamfer_dx   = chamfer_w / tan(chamfer_angle);   // run along top face (mm)

// Top face dimensions after the four chamfers
top_x        = block_x - 2 * chamfer_dx;         // 96 mm
top_y        = block_y - 2 * chamfer_dh;         // 36 mm

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Four 45-degree chamfers on the top edges, extended past the cut faces
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x/2 - chamfer_dx : -block_x/2,
                   sy > 0 ? block_y/2 - chamfer_dh : -block_y/2,
                   block_h - chamfer_dh])
            cube([chamfer_dx, chamfer_dh, chamfer_dh + eps]);
    }
}
