// Display base with bevelled top edges
// Print orientation: flat on XY plane, top face at z = 10

// ---------- Parameters ----------
block_x      = 100;   // block length in X (mm)
block_y      = 40;    // block width in Y (mm)
block_h      = 10;    // block height in Z (mm)

chamfer_w    = 2;     // chamfer width along the top edge (mm)
chamfer_angle = 45;   // chamfer angle relative to the top face (deg)

eps          = 0.5;   // overcut so cutters pass beyond the top faces (mm)

$fn = 64;

// ---------- Derived ----------
// With a 45-degree chamfer the height lost equals the width run:
// 10 - 2 * 2 = 6 mm of vertical side, top face shrinks by 2 * 2 in X and Y
top_x = block_x - 2 * chamfer_w;   // 96 mm
top_y = block_y - 2 * chamfer_w;   // 36 mm
side_h = block_h - 2 * chamfer_w;  // 6 mm

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Chamfer cutters along the four top edges, extended above the top face
    // (the bottom edges remain sharp)
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x / 2 - eps : -block_x / 2 - eps,
                   sy > 0 ? block_y / 2 - eps : -block_y / 2 - eps,
                   block_h - side_h])
            // 45-degree ramp: for every mm in X and Y, Z rises by 1 mm
            cube([chamfer_w + eps, chamfer_w + eps, side_h + eps]);
    }
}
