eps = 0.5;       // extension of cutters past faces (mm)

// Derived
w0 = plate_w - 2 * round_r;   // width of central rectangular region
h0 = plate_l - 2 * round_r;   // length of central rectangular region

difference() {
    // Plate body, centred in X/Y, resting on z = 0
    translate([-plate_l / 2, -plate_w / 2, 0])
        linear_extrude(height = plate_t)
            hull() {
                for (sx = [-1, 1], sy = [-1, 1])
                    translate([sx * round_r, sy * round_r, 0])
                        circle(r = round_r);
                translate([-h0 / 2, -w0 / 2, 0])
                    cube([h0, w0, 1]);
                translate([h0 / 2, -w0 / 2, 0])
                    cube([h0, w0, 1]);
                translate([-h0 / 2, w0 / 2, 0])
                    cube([h0, w0, 1]);
                translate([h0 / 2, w0 / 2, 0])
                    cube([h0, w0, 1]);
            }

    // Cable tie hole through the plate
    translate([tie_x, tie_y, -eps])
        cylinder(d = tie_d, h = plate_t + 2 * eps);
}
