spacer_d        = 24;    // spacer outer diameter
spacer_h        = 12;    // spacer total height
screw_d         = 3.4;   // socket-head screw diameter
counterbore_d   = 6.5;   // counterbore diameter
counterbore_h   = 5;     // counterbore depth from top face
eps             = 0.5;   // cutter overshoot past faces
$fn             = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Main cylinder
    cylinder(d = spacer_d, h = spacer_h);

    // Through hole for screw shank
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = spacer_h + 2 * eps);

    // Coaxial counterbore from top face
    translate([0, 0, spacer_h - counterbore_h])
        cylinder(d = counterbore_d, h = counterbore_h + eps);
}
