rail_top_w  = 16;    // dovetail rail width at its top face (z = 12) (mm)
rail_h      = 8;     // dovetail rail height above the plate (mm)

eps         = 0.5;   // overcut so cutting shapes pass beyond faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Derived ----------------
rail_top_z  = plate_thk + rail_h;   // top face height of the rail (12 mm)

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: a trapezoidal block centred on y = 0, flaring outward
    translate([-plate_len/2, -rail_top_w/2 - eps, plate_thk])
        cube([plate_len, rail_top_w + 2*eps, rail_h]);
