// Spacer washers - a row of identical flat ring washers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 4;    // number of washers in the row
washer_od      = 30;   // outer diameter of each washer (mm)
washer_id      = 10.5; // inner diameter of each washer (mm)
washer_t       = 2;    // thickness of each washer (mm)
washer_gap     = 8;    // centre-to-centre spacing between washers (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)

$fn = 96;              // smoothness of curved shapes

// ---------------- Derived ----------------
row_length = (washer_count - 1) * washer_gap;  // span of the row, centred on origin

// ---------------- Model ----------------
difference() {
    // Solid disc from which the central hole is cut
    cylinder(d = washer_od, h = washer_t);

    translate([0, 0, -eps])
        cylinder(d = washer_id, h = washer_t + 2 * eps);
}

// Stack the washers in a single row along X, centred on y = 0
for (i = [0 : washer_count - 1]) {
    translate([i * washer_gap - row_length / 2, 0, 0])
        // Each washer is a separate part: small overlap into neighbours
        // ensures a clean union with no touching faces.
        linear_extrude(height = washer_t + 0.01)
            circle(d = washer_od);
}
