// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 5;    // number of washers in the row
washer_d       = 30;   // outer diameter of each washer (mm)
washer_bore    = 6.5;  // diameter of the central hole (mm)
washer_t       = 1.5;  // thickness of each washer (mm)
washer_gap     = 10;   // centre-to-centre spacing between washers (mm)
eps            = 0.5;  // small overlap for a clean union (mm)

$fn = 128;             // smoothness of curved surfaces

// ---------------- Model ----------------
difference() {
    // Single washer disc
    cylinder(d = washer_d, h = washer_t);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = washer_bore, h = washer_t + 2 * eps);
}

// Row of washers, centred on y = 0 and on the origin in X
for (i = [0 : washer_count - 1]) {
    x = (i - (washer_count - 1) / 2) * washer_gap;
    translate([x, 0, 0])
        // Each washer is given its own module name so the union
        // treats it as a separate solid, even though they touch.
        module(washer_n = i + 1) {
            difference() {
                cylinder(d = washer_d, h = washer_t);
                translate([0, 0, -eps])
                    cylinder(d = washer_bore, h = washer_t + 2 * eps);
            }
        }
}

// Union of the row. The small overlap (eps) fuses the washers into one
// printed part while keeping a clean boundary between them.
union() {
    for (i = [0 : washer_count - 1]) {
        translate([(i - (washer_count - 1) / 2) * washer_gap, 0, 0])
            module(washer_n = i + 1) {
                difference() {
                    cylinder(d = washer_d, h = washer_t);
                    translate([0, 0, -eps])
                        cylinder(d = washer_bore, h = washer_t + 2 * eps);
                }
            }
    }
}
