block_wid   = 30;   // width along Y
block_ht    = 15;   // height along Z

// ---- Groove parameters ----
groove_n     = 3;   // number of V-grooves
groove_pitch = 18;  // centre-to-centre spacing along X
groove_w     = 10;  // groove width at top surface (mm)
groove_d     = 5;   // groove depth from top surface (mm)
groove_angle = 90;  // V-profile included angle (degrees)

// ---- Derived ----
overcut = 0.5;              // extension past faces to avoid coplanar surfaces
$fn = 96;                   // curve resolution

// Half-angle of the V-groove, used in the cutting cylinder
groove_half_angle = groove_angle / 2;

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        x = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x - block_len / 2, -block_wid / 2 - overcut, block_ht - groove_d])
            rotate([0, 90, 0])
                cylinder(d = groove_w, h = groove_d + overcut, angle = groove_angle);
    }
}
