groove_wt    = 10;  // groove width at top surface (mm)
groove_depth = 5;   // groove depth from top surface (mm)
groove_angle = 90;  // V-profile included angle (degrees)

// ---- Derived ----
overcut = 0.5;      // extension of cutters past the top face
x0 = -(groove_n - 1) * groove_pitch / 2;  // first groove centre X

// V-groove leg slope (1 / tan(angle/2))
leg_slope = 1 / tan(groove_angle / 2);

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([x0 + i * groove_pitch, -block_wid / 2 - overcut, block_ht - groove_depth])
            linear_extrude(height = block_wid + 2 * overcut)
                polygon([[-groove_wt / 2, -leg_slope * (groove_wt / 2)],
                         [ groove_wt / 2, -leg_slope * (groove_wt / 2)],
                         [ groove_wt / 2,  leg_slope * (groove_wt / 2)],
                         [-groove_wt / 2,  leg_slope * (groove_wt / 2)]]);
    }
}
