// Glass stirring rod rest - rectangular block with V-shaped grooves along Y
// Print orientation: base on the bed, grooves open upward (+Z)

// ---------------- Parameters ----------------
block_len   = 84;    // block length along X (mm)
block_wid   = 40;    // block width along Y (mm)
block_ht    = 18;    // block height along Z (mm)

groove_n     = 5;    // number of V-grooves
groove_pitch = 15;   // centre-to-centre spacing along X (mm)
groove_wt    = 8;    // groove width at the top surface (mm)
groove_d     = 4;    // groove depth from the top surface (mm)

eps          = 0.5;  // overcut past faces to avoid coplanar surfaces (mm)

$fn = 96;

// ---------------- Derived ----------------
// For a 90-degree V-groove the two faces are at 45 degrees.
// Face slope (rise/run) = 1, so the width grows by 2*eps per mm of overcut.
groove_dz = groove_d + eps;                     // vertical extent of the cut (mm)
groove_w0 = groove_wt - 2 * eps * tan(45);      // width at z = 0 for the overcut (mm)

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running the full width along Y, centred along X
    for (i = [0 : groove_n - 1]) {
        x = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x - block_len / 2 - eps, -block_wid / 2 - eps, block_ht - groove_dz])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-eps, -groove_w0 / 2], [-eps, groove_w0 / 2],
                         [groove_dz, groove_w0 / 2 + eps * tan(45)],
                         [groove_dz, -groove_w0 / 2 - eps * tan(45)]]);
    }
}
