// Extending the groove eps past the top surface keeps the 90-degree profile:
// the overcut adds eps to the width at the top and 2*eps to the depth.
groove_top_x = groove_wt / 2 + eps * tan(45);   // x offset of wall at top surface
groove_full_depth = groove_depth + eps * 2;     // depth at z = top + eps

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running the full width along Y, centred along X
    for (i = [0 : groove_n - 1]) {
        x_c = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x_c - groove_wt / 2, -block_wid / 2 - eps,
                   block_ht - groove_depth])
            // 90-degree V prism, overcut past the top face
            linear_extrude(height = groove_full_depth)
                polygon([[-groove_wt / 2, 0], [groove_wt / 2, 0],
                         [0, block_wid + 2 * eps]]);
    }
}
