```openscad
// Glass stirring rod rest
// Print orientation: base on bed (z = 0), grooves facing up

// ---------- Parameters ----------
block_len   = 90;    // block length along X (mm)
block_wid   = 40;    // block width along Y (mm)
block_ht    = 15;    // block height along Z (mm)

groove_n     = 4;    // number of V-grooves
groove_pitch = 20;   // centre-to-centre spacing along X (mm)
groove_wt    = 8;    // groove width at top surface (mm)
groove_d    = 4;     // groove depth from top surface (mm)

eps         = 0.5;   // cutter overshoot past top face (mm)

$fn = 96;

// ---------- Derived ----------
// 90-degree V means the two faces are at 45 degrees.
// Thus the horizontal offset between the two cutter walls equals the
// groove width at any height, and the depth is half that width.
groove_depth = groove_wt / 2;              // 4 mm for a 90-degree V
cutter_len   = groove_pitch * (groove_n - 1); // distance from first to last groove centre

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        x = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x, -block_wid / 2 - eps, block_ht - groove_depth])
            // 45-degree walls: cylinder axis along Y, radius = half groove width
            cylinder(h = block_wid / 2 + eps, r = groove_wt / 2, $fn = 96);
    }
}
