// Cross-shaped stabiliser for a tall bottle
// Print orientation: flat on the bed, z = 0 up to plate_t

// ---------- Parameters ----------
plate_t      = 3;     // plate thickness (Z)
bar_len      = 70;    // length of each arm (X and Y)
bar_w        = 10;    // width of each arm
hole_d       = 4.5;   // diameter of central and end holes
end_dist     = 30;    // distance from origin to centre of each end hole
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Model ----------
difference() {
    // Main cross plate
    union() {
        for (dir = [0, 90])
            rotate([0, 0, dir])
                translate([-bar_len/2, -bar_w/2, 0])
                    cube([bar_len, bar_w, plate_t]);
    }

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2*eps);

    // End holes, centred 30 mm from the origin on each arm
    for (dir = [0, 90])
        rotate([0, 0, dir])
            translate([end_dist, 0, -eps])
                cylinder(d = hole_d, h = plate_t + 2*eps);
}
```

