// Wall plate with keyhole slot - hangs on a screw head through the rounded end of the slot
// Print orientation: flat on the bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
plate_l   = 60;    // plate length along X (mm)
plate_w   = 35;    // plate width along Y (mm)
plate_t   = 5;     // plate thickness along Z (mm)

hole_d    = 10;    // round hole diameter (mm)
slot_w    = 4;     // straight slot width (mm)
slot_cx   = 15;    // centre X of rounded slot end (mm)
slot_cy   = 0;     // centre Y of rounded slot end (mm)

eps       = 0.5;   // cutter overshoot past faces (mm)
$fn       = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Plate body, centred in X/Y, resting on z = 0
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Keyhole: round hole + straight slot + rounded end
    translate([0, 0, -eps])
        union() {
            // Round hole centred at origin
            cylinder(d = hole_d, h = plate_t + 2*eps);

            // Straight slot running +X from the centre
            translate([0, -slot_w/2, -eps])
                cube([slot_cx - hole_d/2 - eps, slot_w, plate_t + 2*eps]);

            // Rounded slot end centred at (slot_cx, slot_cy)
            translate([slot_cx - slot_w/2 - eps, slot_cy - slot_w/2, -eps])
                hull() {
                    for (dx = [-slot_w/2 - eps, slot_w/2 - eps])
                        translate([dx, 0, -eps])
                            cylinder(d = slot_w + 2*eps, h = plate_t + 2*eps, $fn = 64);
                }
        }
}
