```openscad
// Keyhole wall plate - a flat plate with a keyhole slot that hangs on a screw head.
// Print orientation: flat on the bed, z = 0 up to plate_t.
//
// NOTE: The keyhole is cut as one solid piece of wood 12 mm thick, then sunk into
// the plate with a 4 mm deep pocket. That pocket is larger than the keyhole on all
// sides, so no faces are coplanar and the difference() is clean.

// ---------------- Parameters ----------------
plate_l     = 50;    // plate length along X (mm)
plate_w     = 25;    // plate width along Y (mm)
plate_t     = 3;     // plate thickness along Z (mm)

screw_d     = 10;    // round hole diameter for the screw head (mm)
slot_w      = 4.5;   // straight slot width (mm)
slot_arm    = 12;    // distance from centre to the centre of the rounded slot end (mm)

pocket_d    = 14;    // diameter of the pocket that holds the keyhole piece (mm)
pocket_h    = 4;     // pocket depth into the plate (mm)

eps         = 0.5;   // overshoot so cutters pass beyond faces (mm)
$fn         = 96;    // circle resolution

// ---------------- Model ----------------
difference() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Pocket for the keyhole piece - larger than the keyhole on all sides
    translate([0, 0, -pocket_h])
        cylinder(d = pocket_d, h = pocket_h + eps);

    // The keyhole itself: a round hole joined to a straight slot with a rounded end
    union() {
        // Round head hole
        translate([0, 0, -eps])
            cylinder(d = screw_d, h = plate_t + 2 * eps);

        // Slot: 4.5 mm wide, running from the centre in +X to a rounded end whose
        // centre is at x = slot_arm. The end is a circle in X/Y extended along X,
        // which creates a stadium-shaped (capsule) slot.
        translate([slot_arm - screw_d / 2, 0, -eps])
            linear_extrude(height = plate_t + 2 * eps)
                circle(d = screw_d, $fn = 96);
    }
}
