// Stepped riser - a solid 3-step staircase, extruded along Y, for setting samples at different heights.
// Print orientation: base on the bed (z = 0), steps climbing in +X.
// Units: mm

// ---------- Parameters ----------
step_count   = 3;    // number of steps
step_length  = 10;   // X-length of each step
step_height  = 8;    // height gain of each step over the previous one
top_height   = 24;   // height of the top step (check: step_height * step_count)
extrude_y    = 20;   // Y-extent of the staircase, from y = 0
overcut      = 0.5;  // extra length so cutters pass through the end faces

$fn = 64;

// ---------- Model ----------
difference() {
    // Solid block that contains the staircase
    translate([0, 0, 0])
        cube([step_count * step_length, extrude_y, top_height]);

    // Empty spaces between the steps, cut right through
    for (i = [0 : step_count - 1]) {
        x0 = i * step_length;
