block_y      = 60;    // block width in Y (mm)
block_h      = 10;    // block height in Z (mm)

chamfer_w    = 4;     // chamfer width along the edge (mm)
chamfer_angle = 45;   // chamfer angle relative to the top face (deg)

top_x        = block_x - 2 * chamfer_w * cos(chamfer_angle);   // top face length in X (92)
top_y        = block_y - 2 * chamfer_w * cos(chamfer_angle);   // top face width in Y (52)
side_h       = block_h - chamfer_w * sin(chamfer_angle);       // vertical side height (6)

eps          = 0.5;    // overcut so cutters pass beyond faces

$fn = 64;

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // 45-degree chamfers along all four top edges
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x/2 - eps : -block_x/2,
                   sy > 0 ? block_y/2 - eps : -block_y/2,
                   block_h - eps])
            cube([chamfer_w * cos(chamfer_angle) + eps,
                  chamfer_w * cos(chamfer_angle) + eps,
                  chamfer_w * sin(chamfer_angle) + eps]);
    }
}
