// Gas cylinder label tag - flat plate with rounded corners and cable tie hole
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Plate ----
plate_l = 80;    // plate length along X
plate_w = 30;    // plate width along Y
plate_t = 3;     // plate thickness (Z)

// ---- Corner radius ----
r = 3;           // rounded corner radius (seen from above)

// ---- Cable tie hole ----
tie_d = 6;       // hole diameter
tie_x = -33;     // hole centre X
tie_y = 0;       // hole centre Y

// ---- Cutting overlap ----
eps = 0.5;       // extension past faces to avoid coplanar surfaces

// Rounded corner offset: moves a rectangle with corners at (±plate_l/2, ±plate_w/2)
// inward by r along both X and Y, leaving a 90 degree corner with a circular arc.
function corner_off() = plate_l/2 - r;

difference() {
    // Plate body
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Cut out the four rounded corners (2D shapes, extruded through the plate)
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * corner_off(), sy * corner_off(), -eps])
            union() {
                translate([r, r, 0])
                    cube([corner_off(), corner_off(), plate_t + 2*eps]);
                translate([-r, -r, 0])
                    cube([corner_off(), corner_off(), plate_t + 2*eps]);
                cylinder(r = r, h = plate_t + 2*eps, $fn = 64);
            }

    // Cable tie hole
    translate([tie_x, tie_y, -eps])
        cylinder(d = tie_d, h = plate_t + 2*eps, $fn = 64);
}
