// Flask support ring with three round legs
// Print orientation: ring top face at z = 50, legs run down to z = 0

// ---------- Parameters ----------
ring_outer_d      = 70;   // ring outer diameter
ring_inner_d      = 50;   // ring inner (bore) diameter
ring_thickness    = 4;    // ring thickness (Z)
ring_top_z        = 50;   // ring top face height
leg_d             = 6;    // leg diameter
leg_count         = 3;    // number of legs
leg_circle_d      = 60;   // leg axes circle diameter
leg_angle         = 120;  // angle between leg axes (degrees)
leg_first_on_x    = true; // first leg on +X axis
overlap           = 0.5;  // leg overlap into ring for a clean union
$fn               = 96;   // curve resolution

// ---------- Derived ----------
leg_bottom_z = 0;                        // legs end at the bed
ring_bottom_z = ring_top_z - ring_thickness; // = 46
leg_circle_r = leg_circle_d / 2;

// ---------- Model ----------
union() {
    // Flat ring (annulus)
    difference() {
        cylinder(d = ring_outer_d, h = ring_thickness, $fn = 128);
        translate([0, 0, ring_bottom_z])
            cylinder(d = ring_inner_d, h = ring_thickness + 0.01, $fn = 128);
    }

    // Legs, placed on the circle, first on +X
    for (i = [0 : leg_count - 1]) {
        rotate([0, 0, leg_angle * i])
            translate([leg_circle_r, 0, 0])
                cylinder(d = leg_d,
                         h = ring_bottom_z - overlap + 0.01, // into the ring
                         $fn = 64);
    }
}
