// Print orientation: ring top face at z = 50, legs run down to z = 0

// ---------- Parameters ----------
ring_outer_d     = 70;   // ring outer diameter
ring_inner_d     = 50;   // ring inner (bore) diameter
ring_thickness   = 4;    // ring thickness (Z)
ring_top_z       = 50;   // ring top face height
leg_d            = 6;    // leg diameter
leg_count        = 3;    // number of legs
leg_circle_d     = 60;   // diameter of circle the leg axes lie on
leg_angle        = 120;  // angle between legs (degrees)
leg_start_angle  = 0;    // first leg on +X axis
overlap          = 0.5;  // leg overlap into ring for a clean union
$fn              = 96;   // curve resolution

// ---------- Derived ----------
leg_bottom_z = ring_top_z - ring_thickness - overlap;  // leg start (z = 45.5)
leg_top_z    = ring_top_z + overlap;                   // leg top (z = 50.5)

// ---------- Model ----------
union() {
    // Flat annulus ring
    difference() {
        cylinder(d = ring_outer_d, h = ring_thickness, $fn = 128);
        translate([0, 0, ring_top_z - ring_thickness])
            cylinder(d = ring_inner_d, h = ring_thickness + 0.01, $fn = 128);
    }

    // Three legs, axes on the specified circle
    for (i = [0 : leg_count - 1]) {
        a = leg_start_angle + i * leg_angle;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), leg_bottom_z])
            cylinder(d = leg_d, h = leg_top_z - leg_bottom_z, $fn = 64);
    }
}
```

