```openscad
// Dovetail rail mounted on a base plate
// Units: mm

$fn = 64;

// Base plate
plate_len   = 120;   // plate length along X
plate_wid   = 40;    // plate width along Y
plate_thk   = 4;     // plate thickness (z = 0 to 4)

// Dovetail rail
rail_base_w = 10;    // rail width at plate top (z = 4)
rail_top_w  = 14;    // rail width at top face (z = 10)
rail_h      = 6;     // rail height above plate (z = 4 to 10)
rail_over   = 0.01;  // cutter overshoot past plate faces

// Check: trapezoid flares outward (base < top)
assert(rail_base_w < rail_top_w, "Rail must flare outward as it rises.");

difference() {
    union() {
        // Base plate, centred in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Dovetail rail, centred on y = 0, running full length along X
        translate([-plate_len/2, -rail_base_w/2, plate_thk])
            linear_extrude(height = rail_h + rail_over)
                polygon([[-rail_base_w/2, 0], [rail_base_w/2, 0],
                         [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
    }

    // Clean up coplanar faces: cut through the plate at z = 4 and z = 10
    translate([-plate_len/2 - rail_over, -rail_top_w/2 - rail_over, plate_thk])
        cube([plate_len + 2*rail_over, rail_top_w + 2*rail_over, rail_h]);

    translate([-plate_len/2 - rail_over, -rail_base_w/2 - rail_over, 0])
        cube([plate_len + 2*rail_over, rail_base_w + 2*rail_over, plate_thk + rail_over]);
}
```

