// Spacer washers - a row of identical flat ring washers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 5;    // number of washers in the row
washer_od      = 30;   // outer diameter of each washer (mm)
washer_id      = 8.5;  // hole diameter of each washer (mm)
washer_t       = 3;    // thickness of each washer (mm)
washer_gap     = 8;    // centre-to-centre spacing between washers (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)
$fn            = 128;  // facet count for round features

// ---------------- Model ----------------
difference() {
    // Solid disc for each washer
    for (i = [0 : washer_count - 1]) {
        translate([(i - (washer_count - 1) / 2) * washer_gap, 0, 0]) {
            cylinder(d = washer_od, h = washer_t);
        }
    }

    // Through-hole in each washer
    for (i = [0 : washer_count - 1]) {
        translate([(i - (washer_count - 1) / 2) * washer_gap, 0, -eps]) {
            cylinder(d = washer_id, h = washer_t + 2 * eps);
        }
    }
}
