    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([x0 + i * groove_pitch, -block_wid / 2 - eps,
                   block_ht - groove_d])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-gt / 2, 0], [gt / 2, 0],
                         [gt / 2, block_wid], [-gt / 2, block_wid]]);
