            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-groove_wt / 2, -slope * (block_ht - groove_depth + eps)],
                         [ groove_wt / 2, -slope * (block_ht - groove_depth + eps)],
                         [ groove_wt / 2,  slope * (block_ht - groove_depth + eps)],
