// Split collet for tube grip
// Print orientation: standing on bed, slots open at top end

// ---- Dimensions (mm) ----
tube_od      = 20;   // outer diameter of round tube
bore         = 16;   // diameter of bore through tube
height       = 30;   // tube height (z = 0 to z = 30)
slot_width   = 1.5;  // width of each straight slot
slot_depth   = 10;   // slots run from top end down to z = 20
slot_count   = 4;    // number of slots, evenly spaced
first_slot_x = 1;    // first slot centred on +X axis (X > 0)

// ---- Modelling parameters ----
eps = 0.5;           // overshoot for clean boolean cuts
$fn = 96;            // facet count for round features

// ---- Model ----
difference() {
    // Main tube body
    cylinder(d = tube_od, h = height);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = bore, h = height + 2 * eps);

    // Axial slots cut from top end down to z = 20
    for (i = [0 : slot_count - 1]) {
        rotate([0, 0, i * 360 / slot_count])
            translate([first_slot_x > 0 ? 1 : -1, 0, height - slot_depth])
                cube([slot_width, tube_od / 2 + 1, slot_depth + eps]);
    }
}
