    // Centre hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2*eps);

    // Four arm-end holes, centred 29 mm from the origin
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * end_dist, sy * end_dist, -eps])
            cylinder(d = hole_d, h = plate_t + 2*eps);
