// Stepped riser - solid staircase of 4 equal steps, print orientation: base on bed,
// climbing in +X. NOVEL general part.
//

// ---- Parameters ----
step_count   = 4;     // number of steps
step_length  = 12;    // X length of each step (mm)
step_height  = 8;     // height increase per step (mm)
first_height = 8;     // height of first step (mm)
top_height   = 32;    // height of top step (mm)
extrusion    = 40;    // Y length of the profile (mm)
eps          = 0.5;   // cutter overshoot past faces (mm)

// Check: first_height + (step_count - 1) * step_height = 32 mm
assert(abs(first_height + (step_count - 1) * step_height - top_height) < 0.001,
       "Height arithmetic does not match");

// ---- Model ----
difference() {
    // Solid block covering the full staircase volume
    translate([0, 0, 0])
        cube([step_count * step_length, extrusion, top_height]);

    // Cut out the empty space under the treads, from y = 0 to y = extrusion
    for (i = [0 : step_count - 1]) {
        x0 = i * step_length;
        // This cutter runs from x = x0 - eps up to x = x0 + step_length + eps.
        // At the top end it is slightly shorter (by eps) so the last face
        // is not coplanar and the solid remains watertight.
        translate([x0 - eps, 0, first_height + i * step_height])
            cube([step_length + 2 * eps, extrusion,
                  eps + (i == step_count - 1 ? 0.01 : step_height)]);
    }
}
```

```openscad
// Stepped riser - solid staircase of 4 equal steps, print orientation: base on bed,
// profile climbs in +X direction. NOVEL general part.
//

$fn = 64;

// ---- Dimensions (mm) ----
step_count   = 4;     // number of steps
step_length  = 12;    // X length of each step
step_height  = 8;     // height gain of each step over the previous one
top_height   = 32;    // height of the top step (check: step_height * step_count)
end_x        = 48;    // X position of the top step's far face (check: step_length * step_count)
extrude_y    = 40;    // length along Y, from y = 0 to y = 40
overcut      = 0.5;   // extra length so cutters pass cleanly through faces

// Derived
first_height = step_height;                  // first step height (same as step_height)
x0           = -step_length / 2;            // X start of the first step
y0           = 0;
z0           = 0;

difference() {
    // Main body: union of the steps, each solid down to the bed
    union() {
        for (i = [0 : step_count - 1]) {
            translate([x0 + i * step_length - step_length / 2, y0, z0])
                cube([step_length, extrude_y, first_height + i * step_height]);
        }
    }

    // Side cutters, running through the part along Y
    translate([end_x - step_length / 2 - overcut, -extrude_y / 2 - overcut, z0])
        cube([step_length, extrude_y + 2 * overcut, top_height]);

    translate([x0 - step_length / 2 - overcut, -extrude_y / 2 - overcut, z0])
        cube([step_length, extrude_y + 2 * overcut, top_height]);
}
