chamfer_angle = 45;   // chamfer angle from the horizontal (deg)

eps          = 0.5;   // overshoot for clean boolean cuts (mm)

// Derived: top face size after chamfers
top_x = block_x - 2 * chamfer_w;   // 52
top_y = block_y - 2 * chamfer_w;   // 42

// Derived: height of the vertical side faces
// (chamfer runs up for 4*sin(45) = 2.828 mm, so vertical part is 10 - 2.828)
side_h = block_h - chamfer_w * sin(chamfer_angle);

$fn = 64;

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Four top-edge chamfers, cut from the top face downward
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x/2 - chamfer_w : -block_x/2,
                   sy > 0 ? block_y/2 - chamfer_w : -block_y/2,
                   block_h - eps])
            // 45-degree ramp: for every 1 mm in X/Y, go down 1 mm in Z
            cube([chamfer_w, chamfer_w, chamfer_w * sin(chamfer_angle) + eps]);
    }

    // Bottom edges stay sharp: no cuts up from z = 0
}
