                   sy > 0 ? block_y/2 - chamfer_w : -block_y/2,
                   block_h - chamfer_h])
            cylinder(r = chamfer_w / cos(chamfer_angle),
                     h = cut_ext_h + chamfer_h + eps,
                     $fn = 64);
