// Circuit board spacer with sunk socket-head screw
// Print orientation: base on the bed (z = 0), counterbore facing up

// ---------- Parameters ----------
spacer_d        = 20;    // spacer outer diameter
spacer_h        = 15;    // spacer total height
screw_hole_d    = 5.5;   // through-hole diameter for socket-head screw
counterbore_d   = 10;    // counterbore diameter (coaxial)
counterbore_h   = 5;     // counterbore depth from top face
eps             = 0.5;   // cutter overshoot past faces
$fn             = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Main cylinder
    cylinder(d = spacer_d, h = spacer_h);

    // Through-hole for screw
    translate([0, 0, -eps])
        cylinder(d = screw_hole_d, h = spacer_h + 2 * eps);

    // Coaxial counterbore from top face
    translate([0, 0, spacer_h - counterbore_h])
        cylinder(d = counterbore_d, h = counterbore_h + eps);
}
