```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail builds upward (+Z)

// ---------- Parameters ----------
plate_len      = 60;    // base plate length (X)
plate_wid      = 36;    // base plate width (Y)
plate_thk      = 4;     // base plate thickness (Z)

rail_bot_w     = 14;    // rail width at bottom face (z = 4), where it meets plate
rail_top_w     = 18;    // rail width at top face (z = 9)
rail_h         = 5;     // rail height (top face at z = 9 - bottom at z = 4)

overcut        = 0.5;   // extra length so cutters pass through end faces
$fn            = 96;    // curve resolution

// ---------- Derived ----------
rail_top_z     = plate_thk + rail_h;   // top face of rail (z = 9)
slope          = (rail_top_w - rail_bot_w) / (2 * rail_h);  // flare per mm height

// ---------- Model ----------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail, centred on y = 0, built up from the plate
    translate([-plate_len/2, -rail_bot_w/2, plate_thk])
        linear_extrude(height = rail_h)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
}

// ---------- Sliding cutters ----------
difference() {
    // The part (solid)
    union() {
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        translate([-plate_len/2, -rail_bot_w/2, plate_thk])
            linear_extrude(height = rail_h)
                polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                         [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
    }

    // Two cutters running along X, centred on y = 0
    for (z = [plate_thk + 0.5, rail_top_z - 0.5]) {
        w = rail_bot_w + 2 * slope * (z - plate_thk);   // rail width at this z
        translate([-plate_len/2 - overcut, -w/2, z])
            cube([plate_len + 2 * overcut, w, 1]);
    }
}
