// Sliding mount with dovetail rail
// Print orientation: base plate on the bed, rail pointing up (+Z)

// ---------- Parameters ----------
plate_len      = 80;    // base plate length (X)
plate_wid      = 30;    // base plate width (Y)
plate_thk      = 6;     // base plate thickness (Z)

rail_bot_w     = 12;    // rail width at bottom face (z = plate_thk)
rail_top_w     = 18;    // rail width at top face (z = plate_thk + rail_h)
rail_h         = 8;     // rail height (top face at z = 14)

eps            = 0.5;   // overcut for clean boolean differences
$fn            = 96;    // curve resolution

// ---------- Derived ----------
rail_x0 = -(rail_bot_w / 2) + eps * 2;   // lower trapezoid X start
rail_x1 = (rail_bot_w / 2) - eps * 2;   // lower trapezoid X end
rail_x2 = (rail_top_w / 2) - eps;       // upper trapezoid X end
rail_x3 = -(rail_top_w / 2) + eps;      // upper trapezoid X start

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail (two trapezoids fused along X)
    difference() {
        hull() {
            translate([rail_x0, 0, plate_thk])
                cube([plate_len, rail_bot_w, rail_h]);
            translate([rail_x1, 0, plate_thk])
                cube([plate_len, rail_bot_w, rail_h]);
            translate([rail_x2, 0, plate_thk + rail_h / 2])
                cube([plate_len, rail_top_w, rail_h / 2 + eps]);
            translate([rail_x3, 0, plate_thk + rail_h / 2])
                cube([plate_len, rail_top_w, rail_h / 2 + eps]);
        }
        // Cut through the plate so the rail fuses with it
        translate([rail_x0, 0, -eps])
            cube([plate_len, rail_bot_w, plate_thk + 2 * eps]);
        translate([rail_x1, 0, -eps])
            cube([plate_len, rail_bot_w, plate_thk + 2 * eps]);
    }
