```openscad
// Dovetail rail mount
// Print orientation: base plate on the bed, rail flaring upward (+Z)

// ---------- Parameters ----------
plate_len      = 100;   // base plate length (X)
plate_wid      = 40;    // base plate width (Y)
plate_thk      = 4;     // base plate thickness (Z)

rail_bot_w     = 14;    // rail width at plate interface (z = 4)
rail_top_w     = 18;    // rail width at top face (z = 10)
rail_top_z     = 10;    // rail top face height (Z)

eps            = 0.5;   // overcut for clean boolean differences
$fn            = 96;    // curve resolution

// ---------- Derived ----------
rail_h         = rail_top_z - plate_thk;  // rail height above plate (6)
slope          = (rail_top_w - rail_bot_w) / (2 * rail_h);  // flare per mm Z

// ---------- Model ----------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail, centred on y = 0, built in linear steps
    for (z = [plate_thk + i * (rail_h/64) | i = [0:63]]) {
        w = rail_bot_w + 2 * slope * (z - plate_thk);
        translate([-plate_len/2, -w/2, z])
            cube([plate_len, w, (rail_h/64) + eps]);
    }
}
