$fn = 96;                                       // facet count for curved surfaces

// Half-angle of the V-groove, used to compute the side slope
slope = tan(groove_angle / 2);

module groove_cutter() {
    // A wedge-shaped cutter that runs the full width along Y
    translate([0, -block_wid / 2 - overcut, block_ht - groove_d])
        linear_extrude(height = block_wid + 2 * overcut)
            polygon([[-1, 0], [1, 0], [0, -1 / slope], [0, 1 / slope]]);
}

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves cut into the top face, centred along X
    for (i = [0 : groove_n - 1]) {
        x = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x, 0, 0])
            groove_cutter();
    }
}
