// Glass stirring rod rest - rectangular block with V-shaped grooves along Y
// Print orientation: base on the bed, grooves facing up

// ---------- Block ----------
block_l = 90;      // block length along X (mm)
block_w = 50;      // block width along Y (mm)
block_h = 12;      // block height along Z (mm)

// ---------- Grooves ----------
groove_n     = 5;      // number of V-grooves
groove_pitch = 15;     // centre-to-centre spacing along X (mm)
groove_w     = 8;      // groove width at the top surface (mm)
groove_d     = 4;      // groove depth from the top surface (mm)

// ---------- Derived ----------
overcut = 0.5;                          // extension of cutters past the top face (mm)
x0      = -(groove_n - 1) * groove_pitch / 2;  // X position of the first groove (mm)
// leg length of the 90-degree V-cone, used for a clean solid union
leg     = groove_w / 2 / tan(45);       // = 4 mm for a 90-degree V

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_l / 2, -block_w / 2, 0])
        cube([block_l, block_w, block_h]);

    // V-shaped grooves running the full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([x0 + i * groove_pitch - block_l / 2, 0, block_h - groove_d])
            union() {
                // Upper cone (45 degrees), extended above the top face
                translate([0, 0, -overcut])
                    cylinder(h = groove_d + overcut + 0.01, r1 = groove_w / 2, r2 = 0);
                // Lower cone, merged into the solid with a tiny overlap
                translate([0, 0, 0.01])
                    cylinder(h = groove_d - 0.01, r1 = groove_w / 2 + 0.01, r2 = 0);
            }
    }
}
