    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Keyhole: round hole + straight slot with rounded end
    translate([0, 0, -eps])
        union() {
            // Round hole centred at origin
            cylinder(d = hole_d, h = plate_t + 2*eps);

            // Slot running +X from the hole, width slot_w, rounded end centred at (slot_cx, slot_cy)
            translate([0, -slot_w/2, -eps])
                linear_extrude(height = plate_t + 2*eps)
                    circle(d = slot_w, $fn = 64);

            translate([slot_cx - slot_w/2, slot_cy - slot_w/2, -eps])
                hull() {
                    for (sx = [-1, 1])
                        translate([sx * (slot_w/2 - eps), 0, -eps])
                            cylinder(d = slot_w, h = plate_t + 2*eps, $fn = 64);
                }
        }
}
