    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Four 45-degree chamfers cut into the top face,
    // extended past the side faces so no faces are coplanar
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([
            sx > 0 ? block_x/2 - chamfer_w : -block_x/2,
            sy > 0 ? block_y/2 - chamfer_w : -block_y/2,
            block_h - eps
        ])
            cube([chamfer_w, chamfer_w, side_h + 2*eps]);
    }
