// ---------- Derived ----------
// Because the angle is 45 deg, the height lost under a chamfer of width w
// is w * cos(45) = w / sqrt(2). The overcut height is the same.
h_chamfer = chamfer_w / sqrt(2);
t_top     = block_h - h_chamfer;   // height of the vertical sides (8 mm)

// The top face shrinks by 2 * chamfer_w in X and Y
top_x = block_x - 2 * chamfer_w;   // 76 mm
top_y = block_y - 2 * chamfer_w;   // 36 mm

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Chamfer cutters for the four top edges.
    // Each is a cylinder along X or Y whose axis lies in the top face,
    // extended above the top face by eps so the cut is clean.
    // A 45-degree chamfer of width w is cut by a cylinder of radius w / sqrt(2).
    for (sx = [-1, 1], sy = [-1, 1]) {
        r = chamfer_w / sqrt(2);
        translate([sx > 0 ? block_x / 2 - chamfer_w : -block_x / 2 + chamfer_w,
                   sy > 0 ? block_y / 2 - chamfer_w : -block_y / 2 + chamfer_w,
                   block_h - h_chamfer])
            cylinder(r = r, h = h_chamfer + eps, $fn = 64);
