```openscad
// Display base with bevelled top edges
// Print orientation: flat on XY plane, top face at z = 12

// ---- Dimensions (mm) ----
block_x      = 60;    // block length in X
block_y      = 50;    // block width in Y
block_h      = 12;    // block height in Z
chamfer_w    = 4;     // chamfer width (45-degree, along the face diagonal)
top_x        = block_x - 2 * chamfer_w; // top face length in X (52)
top_y        = block_y - 2 * chamfer_w; // top face width in Y (42)
side_h       = block_h - chamfer_w;    // vertical side height (8)

// ---- Modelling parameters ----
eps          = 0.5;   // overshoot for clean boolean cuts
$fn          = 64;

// A 45-degree chamfer along a top edge is a cylinder whose axis lies in the
// top face, runs parallel to the edge, and whose radius equals the diagonal
// width of the chamfer (w * sqrt(2)). Cutting it with two perpendicular planes
// at z = side_h and z = block_h - eps leaves a 45-degree bevelled edge.
chamfer_r    = chamfer_w * sqrt(2);

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Chamfer cylinders for the four top edges
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x / 2 - chamfer_w : -block_x / 2 + chamfer_w,
                   sy > 0 ? block_y / 2 - chamfer_w : -block_y / 2 + chamfer_w,
                   0])
            cylinder(r = chamfer_r, h = block_h + 2 * eps,
                     center = true, $fn = 64);
    }

    // Planes that slice the cylinders at side_h and near the top face,
    // turning the diagonal cuts into 45-degree bevels
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x / 2 - chamfer_w : -block_x / 2 + chamfer_w,
                   sy > 0 ? block_y / 2 - chamfer_w : -block_y / 2 + chamfer_w,
                   side_h])
            cube([chamfer_w * 2 + eps, block_h - side_h + eps, eps]);

        translate([sx > 0 ? block_x / 2 - chamfer_w : -block_x / 2 + chamfer_w,
                   sy > 0 ? block_y / 2 - chamfer_w : -block_y / 2 + chamfer_w,
                   block_h - eps])
            cube([chamfer_w * 2 + eps, block_h - side_h + eps, eps]);
    }
}
