inner_w = plate_w - 2 * corner_r;              // straight section width
area    = plate_l * plate_w - 4 * corner_r * (corner_r - inner_w / 2); // rough area

// ---------- Modules ----------
module rounded_plate() {
    // Build the plate with rounded corners using a superellipse outline
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx * (plate_l / 2 - corner_r),
                       sy * (plate_w / 2 - corner_r),
                       0])
                cylinder(r = corner_r, h = plate_t + 2 * eps, $fn = 96);
    }
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            circle(d = plate_l - 2 * corner_r, h = plate_w - 2 * corner_r, $fn = 96);
}

module tie_hole() {
    translate([tie_x, tie_y, -eps])
        cylinder(d = tie_hole, h = plate_t + 2 * eps, $fn = 64);
}

// ---------- Part ----------
difference() {
    rounded_plate();
    tie_hole();
