// Gas cylinder label tag - flat plate with rounded corners and a cable-tie hole
// Print orientation: flat on the bed, z = 0 up to plate_t

// ---------- Parameters ----------
plate_l   = 50;    // plate length along X (mm)
plate_w   = 20;    // plate width along Y (mm)
plate_t   = 2;     // plate thickness along Z (mm)
corner_r  = 4;     // radius of the four rounded corners (mm)
tie_hole  = 5;     // diameter of the cable-tie hole (mm)
tie_x     = -18;   // hole centre X position (mm)
tie_y     = 0;     // hole centre Y position (mm)
eps       = 0.5;   // cutter overshoot past faces (mm)

$fn = 64;

// ---------- Model ----------
difference() {
    // Main plate body
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Rounded corners, cut into the top face
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_l/2 - corner_r : -plate_l/2,
                   sy > 0 ? plate_w/2 - corner_r : -plate_w/2,
                   plate_t - eps])
            cylinder(r = corner_r, h = eps + 0.01);

    // Cable-tie hole through the full thickness
    translate([tie_x, tie_y, -eps])
        cylinder(d = tie_hole, h = plate_t + 2*eps);
}
