// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail builds upward (+Z)

// ---------------- Parameters ----------------
plate_len    = 80;    // base plate length (X)
plate_wid    = 30;    // base plate width (Y)
plate_thk    = 4;     // base plate thickness (Z)

rail_bot_w   = 12;    // dovetail rail width at plate interface (z = 4)
rail_top_w   = 16;    // dovetail rail width at top face (z = 9)
rail_h       = 5;     // dovetail rail height (z = 4 to 9)

eps          = 0.5;   // overcut for clean boolean differences
$fn          = 96;    // curve resolution

// Derived: rail slope (Y change per X unit)
rail_slope   = (rail_top_w - rail_bot_w) / (2 * rail_h);

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail
    translate([-plate_len/2, 0, plate_thk])
        linear_extrude(height = rail_h + eps)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
}
