// Glass stirring rod rest
// Print orientation: flat on bed, grooves facing up

// ---- Block dimensions ----
block_len   = 84;   // length along X
block_wid   = 30;   // width along Y
block_ht    = 15;   // height along Z

// ---- Groove parameters ----
groove_n     = 5;   // number of V-grooves
groove_pitch = 15;  // centre-to-centre spacing along X
groove_w     = 8;   // groove width at top surface
groove_d     = 4;   // groove depth from top surface
groove_angle = 90;  // V-profile included angle (degrees)

// ---- Derived ----
overcut = 0.5;              // extension past faces to avoid coplanar faces
$fn     = 96;               // curve resolution

// Half-angle of the V-groove used in cylinder with $fn=96
groove_ha = groove_angle / 2;

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves along Y, centred along X
    for (i = [0 : groove_n - 1]) {
        x = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x - overcut, -block_wid/2 - overcut, block_ht - groove_d])
            rotate([0, 90, 0])
                cylinder(h = block_wid + 2 * overcut,
                         r = groove_w / 2 / cos(groove_ha),
                         $fn = 96);
    }
}
