bar_len      = 50;    // length of each arm (X and Y)
bar_w        = 12;    // width of each arm
hole_centre  = 19;    // distance from origin to each arm-end hole centre
hole_d       = 6.5;   // diameter of the two through-holes
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Model ----------
difference() {
    // Plus-sign plate
    union() {
        cube([bar_len, bar_w, plate_t]);   // horizontal arm
        cube([bar_w, bar_len, plate_t]);   // vertical arm
    }

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);

    // Arm-end holes, centred 19 mm from the origin
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * hole_centre, sy * hole_centre, -eps])
            cylinder(d = hole_d, h = plate_t + 2 * eps);
}
