// Print orientation: flat on the bed, z = 0 up to plate_t

// ---------- Parameters ----------
plate_t      = 4;     // plate thickness (Z)
arm_len      = 80;    // length of each arm (X and Y)
arm_w        = 10;    // width of each arm
hole_d       = 5.5;   // diameter of central and end holes
hole_offset  = 35;    // distance from origin to each arm end
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Model ----------
difference() {
    union() {
        // Horizontal bar (along X)
        translate([-arm_len/2, -arm_w/2, 0])
            cube([arm_len, arm_w, plate_t]);

        // Vertical bar (along Y)
        translate([-arm_w/2, -arm_len/2, 0])
            cube([arm_w, arm_len, plate_t]);
    }

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2*eps);

    // Four arm-end holes, centred 35 mm from the origin
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * hole_offset, sy * hole_offset, -eps])
            cylinder(d = hole_d, h = plate_t + 2*eps);
}
```

