```openscad
// Keyhole wall plate - a flat plate with a keyhole slot for hanging on a screw head
// Print orientation: flat on the bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_l   = 60;    // plate length along X (mm)
plate_w   = 30;    // plate width along Y (mm)
plate_t   = 4;     // plate thickness along Z (mm)

hole_d    = 9;     // round part of keyhole diameter (mm)
slot_w    = 4;     // slot width (mm)
slot_cx   = 10;    // centre X of slot's rounded end (mm)
slot_cy   = 0;     // centre Y of slot's rounded end (mm)

eps       = 0.5;   // cutter overshoot past faces (mm)
$fn       = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Plate body, centred in X/Y, resting on z = 0
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Keyhole: round hole + straight slot with a rounded end
    translate([0, 0, -eps])
        union() {
            // Round hole centred at origin
            cylinder(d = hole_d, h = plate_t + 2*eps);

            // Slot running +X from the origin to the rounded end
            translate([0, 0, -eps])
                linear_extrude(height = plate_t + 2*eps)
                    hull() {
                        translate([-slot_w/2, 0]) square([slot_cx - slot_w/2, slot_w]);
                        translate([slot_cx, 0]) circle(d = slot_w, $fn = 64);
                    }
        }
}
```

