$fn = 64;

// ---- Plate ----
plate_l = 70;    // plate length along X (mm)
plate_w = 25;    // plate width along Y (mm)
plate_t = 3;     // plate thickness along Z (mm)

// ---- Corner radius ----
round_r = 5;     // radius of rounded corners (mm)

// ---- Cable tie hole ----
tie_d   = 5;     // hole diameter (mm)
tie_x   = -28;   // hole centre X position (mm)
tie_y   = 0;     // hole centre Y position (mm)

// ---- Cutting overlap ----
eps = 0.5;       // extension of cutters past faces (mm)

// Derived
w0 = plate_w - 2 * round_r;   // straight section width (Y)
h0 = plate_l - 2 * round_r;   // straight section length (X)

module rounded_rect(l, w, r) {
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx * (l / 2 - r), sy * (w / 2 - r), 0])
                circle(r = r);
    }
}

difference() {
    // Plate body
    translate([-plate_l / 2, -plate_w / 2, 0])
        linear_extrude(height = plate_t)
            rounded_rect(plate_l, plate_w, round_r);

    // Cable tie hole
    translate([tie_x, tie_y, -eps])
        cylinder(d = tie_d, h = plate_t + 2 * eps);
}
