// Spacer washers - a row of identical flat ring washers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 5;    // number of washers in the row
washer_d       = 30;   // outer diameter of a washer (mm)
washer_bore    = 6.5;  // diameter of the central hole (mm)
washer_t       = 1.5;  // thickness of a washer (mm)
washer_gap     = 8;    // centre-to-centre spacing between washers (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)

$fn = 96;              // smoothness of curved surfaces

// ---------------- Model ----------------
difference() {
    // Solid disc from which the hole is cut
    cylinder(d = washer_d, h = washer_t);

    // Central through-hole, extended past both faces
    translate([0, 0, -eps])
        cylinder(d = washer_bore, h = washer_t + 2 * eps);
}

// Row of washers, centred on y = 0 and on the origin in X
for (i = [0 : washer_count - 1]) {
    x = (i - (washer_count - 1) / 2) * washer_gap;
    translate([x, 0, 0])
        // Each washer is a distinct part with no overlaps
        difference() {
            cylinder(d = washer_d, h = washer_t);
            translate([0, 0, -eps])
                cylinder(d = washer_bore, h = washer_t + 2 * eps);
        }
}
```

```openscad
// Spacer washers - a row of identical flat ring washers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

$fn = 96;

// ---- Washer dimensions ----
washer_d      = 30;    // outer diameter
washer_bore   = 6.5;   // central hole diameter
washer_t      = 1.5;   // thickness (Z)

// ---- Row parameters ----
washer_count  = 5;     // number of washers in the row
washer_gap    = 8;     // centre-to-centre spacing along X
row_overlap   = 0.01;  // small overlap of the union so the row stays one solid

// ---- Derived ----
row_length = (washer_count - 1) * washer_gap;  // span between end washers
y          = 0;                                // row centred on y = 0

difference() {
    // Single washer, centred in X and Y, resting on z = 0
    cylinder(d = washer_d, h = washer_t);

    // Central hole, extended past both faces to avoid coplanar faces
    translate([0, 0, -1])
        cylinder(d = washer_bore, h = washer_t + 2);
}

// Place the washers in a row along X, then centre the whole row on the origin
for (i = [0 : washer_count - 1]) {
    translate([(i - (washer_count - 1) / 2) * washer_gap, y, 0])
        module = cylinder(d = washer_d, h = washer_t, $fn = 96);
}

// Clean up any tiny overlaps so the washers remain separate parts
difference() {
    union() {
        for (i = [0 : washer_count - 1])
            translate([(i - (washer_count - 1) / 2) * washer_gap, y, 0])
                cylinder(d = washer_d, h = washer_t + row_overlap);
    }
    for (i = [0 : washer_count - 2])
        translate([(i - (washer_count - 1) / 2) * washer_gap + washer_gap / 2, y, -row_overlap])
            cylinder(d = washer_d + 0.02, h = washer_t + 2 * row_overlap);
}
