// Glass stirring rod rest - block with V-shaped grooves along Y
// Print orientation: flat on bed, grooves facing up

// ---- Block dimensions ----
block_len   = 95;   // length along X
block_wid   = 40;   // width along Y
block_ht    = 12;   // height along Z

// ---- Groove parameters ----
groove_n     = 6;   // number of grooves
groove_pitch = 15;  // centre-to-centre spacing along X
groove_wt    = 10;  // groove width at top surface (Z = block_ht)
groove_d     = 5;   // groove depth from top surface
groove_angle = 90;  // V profile angle (degrees)

// ---- Derived ----
overcut = 0.5;              // extension past faces to avoid coplanar surfaces
$fn = 96;                   // curve resolution

// Half-angle of the V groove (from vertical)
groove_ha = (groove_angle / 2) * (180 / PI);

// X position of first groove centre (grooves centred along X)
groove_x0 = -(groove_n - 1) * groove_pitch / 2;

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([groove_x0 + i * groove_pitch - block_len / 2,
                   -block_wid / 2 - overcut,
                   block_ht - groove_d])
            linear_extrude(height = block_wid + 2 * overcut)
                polygon([[-groove_wt / 2, -groove_ha * (groove_wt / 2)],
                         [ groove_wt / 2, -groove_ha * (groove_wt / 2)],
                         [ groove_wt / 2,  groove_ha * (groove_wt / 2)],
                         [-groove_wt / 2,  groove_ha * (groove_wt / 2)]]);
    }
}
