```openscad
// Glass stirring rod rest - block with V-shaped grooves along Y
// Print orientation: base on bed, grooves facing up

// ---------- Parameters ----------
block_len   = 95;    // block length along X (mm)
block_wid   = 40;    // block width along Y (mm)
block_ht    = 12;    // block height along Z (mm)

groove_n    = 6;     // number of V-grooves
groove_pitch = 15;   // centre-to-centre spacing along X (mm)
groove_w_top = 10;   // groove width at top surface (mm)
groove_depth = 5;    // groove depth from top surface (mm)

eps         = 0.5;   // overcut past faces to avoid coplanar faces (mm)

$fn = 96;

// ---------- Derived ----------
// 90-degree V means the two sides meet at a right angle;
// each side has slope 1 (rise = run), so the side wall moves
// 1 mm in X for every 1 mm of height. Extend the side walls
// above the top face so the full V passes through the cut.
side_wid = groove_w_top + 2 * (groove_depth + eps);  // width of V at z = block_ht + eps
first_x  = -(groove_n - 1) * groove_pitch / 2;       // X of first groove centre

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([first_x + i * groove_pitch - block_wid / 2 - eps, 0, 0])
            linear_extrude(height = block_wid + 2 * eps)
                translate([0, -side_wid / 2, block_ht])
                    // Two side walls meeting at a right angle
                    union() {
                        translate([-side_wid / 2, 0, -eps])
                            cube([side_wid, block_wid + 2 * eps, groove_depth + eps]);
                        rotate([0, 90, 0])
                            translate([-side_wid / 2, 0, -eps])
                                cube([side_wid, block_wid + 2 * eps, groove_depth + eps]);
                    }
    }
}
