eps         = 0.5;   // overcut past faces to avoid coplanar faces (mm)

$fn = 96;

// ---------- Derived ----------
// For a 90-degree V groove, the side walls are at 45 degrees.
// Extending the walls up by eps makes the top opening (gt) equal to
// the width at depth d plus 2*eps, keeping the 90-degree profile.
gt = groove_wt + 2 * eps;          // opening width at height (ht - d + eps)
ax = groove_pitch * (groove_n - 1) / 2; // offset of first/last groove from centre

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-shaped grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([-ax + i * groove_pitch, -block_wid / 2 - eps,
                   block_ht - groove_d])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-gt / 2, 0], [gt / 2, 0], [0, -gt / 2]]);
    }
}
