// Stepped riser - solid staircase of 3 equal steps, print orientation: base on bed,
// profile climbs in +X direction. NOVEL general part.
//

$fn = 64;

// ---- Dimensions (mm) ----
step_count   = 3;     // number of steps
step_length  = 15;    // X length of each step
step_height  = 6;     // height gain of each step over the previous
top_height   = 18;    // height of the top step (3 * step_height)
extrusion    = 20;    // Y thickness of the part
start_x      = 0;     // X position of the first step
start_y      = 0;     // Y position of the first step

// ---- Model ----
difference() {
    // Single block covering the full X span of the staircase
    translate([start_x, start_y, 0])
        cube([step_count * step_length, extrusion, top_height]);

    // Cut out the "undercuts" between steps so the profile is a clean ramp
    for (i = [0 : step_count - 2]) {
        x1 = start_x + i * step_length;
        x2 = start_x + (i + 1) * step_length;
        y1 = start_y;
        y2 = start_y + extrusion;
        z1 = i * step_height;
        z2 = (i + 2) * step_height;   // overshoot past the upper face
        translate([x1, y1, z1])
            cube([step_length, extrusion, z2 - z1]);
    }
}
