// Display base with bevelled top edges
// Print orientation: flat on XY plane, top face at z = 10

// ---------- Parameters ----------
block_x      = 100;   // block length in X (mm)
block_y      = 50;    // block width in Y (mm)
block_h      = 10;    // block height in Z (mm)

chamfer_w    = 2;     // chamfer width along the edge (mm)
chamfer_angle = 45;   // chamfer angle relative to the top face (deg)

eps          = 0.5;   // overshoot for clean boolean cuts (mm)
$fn          = 64;    // curve resolution

// ---------- Derived ----------
// Because the chamfer is 45 deg, the height removed from each side is
// equal to the run along the top face: dx = dy = w / tan(angle)
chamfer_dh   = chamfer_w / tan(chamfer_angle);   // height cut from side (mm)
chamfer_dx   = chamfer_w / tan(chamfer_angle);   // run along top face (mm)

// Top face dimensions after the four chamfers
top_x        = block_x - 2 * chamfer_dx;         // 96 mm
top_y        = block_y - 2 * chamfer_dh;         // 46 mm

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Four corner chamfers, extended past the top and side faces
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([
            sx > 0 ? block_x/2 - chamfer_dx : -block_x/2 + chamfer_dx,
            sy > 0 ? block_y/2 - chamfer_dh : -block_y/2 + chamfer_dh,
            block_h - chamfer_dh
        ])
            cube([chamfer_dx, chamfer_dh, chamfer_dh + eps]);
    }
}
