ring_outer_d     = 90;   // ring outer diameter
ring_inner_d     = 74;   // ring inner diameter
ring_thickness   = 4;    // ring thickness (Z)
ring_top_z       = 40;   // ring top face height
leg_d            = 6;    // leg diameter
leg_count        = 3;    // number of legs
leg_circle_d     = 82;   // diameter of circle the leg axes lie on
leg_angle        = 120;  // angle between legs (degrees)
leg_start_angle  = 0;    // first leg on +X axis
overlap          = 0.5;  // leg extends past ring into it for a clean union
$fn              = 96;   // curve resolution

// ---------- Model ----------
union() {
    // Flat ring (annulus)
    difference() {
        cylinder(d = ring_outer_d, h = ring_thickness, $fn = 192);
        translate([0, 0, ring_top_z - overlap])
            cylinder(d = ring_inner_d, h = ring_thickness + 2 * overlap, $fn = 192);
    }

    // Three legs, axes on the specified circle, 120 deg apart
    for (i = [0 : leg_count - 1]) {
        rotate([0, 0, leg_start_angle + i * leg_angle])
            translate([leg_circle_d / 2, 0, ring_top_z - overlap])
                cylinder(d = leg_d, h = ring_thickness + 2 * overlap, $fn = 64);
    }
}
