```openscad
// Circuit board spacer with sunk socket-head screw
// Print orientation: base on the bed (z = 0), counterbore opening at the top.

// ---------- Parameters ----------
spacer_d        = 18;    // cylinder diameter
spacer_h        = 15;    // cylinder height (z = 0 to 15)
hole_d          = 4.5;   // through-hole diameter for screw
counterbore_d   = 8;     // counterbore diameter
counterbore_h   = 4;     // counterbore depth (from top face, z = 11 to 15)
eps             = 0.5;   // overshoot for clean boolean cuts
$fn             = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Main spacer body
    cylinder(d = spacer_d, h = spacer_h);

    // Through-hole for screw
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = spacer_h + 2 * eps);

    // Coaxial counterbore from top face
    translate([0, 0, spacer_h - counterbore_h])
        cylinder(d = counterbore_d, h = counterbore_h + eps);
}
```

