// Sliding mount with dovetail rail
// Print orientation: base plate on the bed, rail pointing up (+Z)

// ---------- Parameters ----------
plate_len      = 80;    // base plate length (X)
plate_wid      = 30;    // base plate width (Y)
plate_thk      = 6;     // base plate thickness (Z)

rail_bot_w     = 10;    // rail width at the plate interface (z = 6)
rail_top_w     = 14;    // rail width at its top face (z = 14)
rail_top_z     = 14;    // rail top face height (Z)

overcut        = 0.5;   // extra length so cutters pass through end faces
$fn            = 96;    // curve resolution

// ---------- Derived ----------
rail_h = rail_top_z - plate_thk;              // rail height above plate (8)
slope  = (rail_top_w - rail_bot_w) / (2 * rail_h);  // flare per mm height

// ---------- Model ----------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail, centred on y = 0, built up from z = 6
    translate([-plate_len/2 - overcut, 0, plate_thk])
        linear_extrude(height = rail_h + overcut)
            polygon([[-rail_bot_w/2, 0], [rail_bot_w/2, 0],
                     [rail_top_w/2, rail_h], [-rail_top_w/2, rail_h]]);
}

// ---------- Clean up ----------
difference() {
    // Cut through the end faces so no coplanar faces remain
    translate([-plate_len/2 - overcut, 0, plate_thk])
        cube([overcut, rail_top_w + 2, rail_h + overcut]);

    translate([plate_len/2, 0, plate_thk])
        cube([overcut, rail_top_w + 2, rail_h + overcut]);
}
