```openscad
// Dovetail rail mounted on a base plate
// Units: mm

$fn = 64;

// Base plate
plate_len   = 100;   // plate length along X
plate_wid   = 40;    // plate width along Y
plate_thk   = 4;     // plate thickness (z = 0 to 4)

// Dovetail rail
rail_base_w = 10;    // rail width at plate top (z = 4)
rail_top_w  = 14;    // rail width at top face (z = 10)
rail_h      = 6;     // rail height above plate (z = 4 to 10)
rail_len    = plate_len; // rail runs full plate length

// Cutting overlap
eps = 0.5;           // extension past cut faces

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    // Trapezoidal cross-section, flaring outward as it rises
    difference() {
        translate([-rail_len/2, -rail_top_w/2, plate_thk])
            linear_extrude(rail_len)
                polygon([[(0, -rail_top_w/2), (0, rail_top_w/2),
                          (rail_h, -rail_base_w/2), (rail_h, rail_base_w/2)]]);
        // Cut into plate along full length, centred on y = 0
        translate([-rail_len/2 - eps, -rail_base_w/2 - eps, plate_thk - eps])
            linear_extrude(rail_len + 2*eps)
                cube([rail_base_w + 2*eps, rail_len + 2*eps, eps]);
    }
}

union() {
    base_plate();
    dovetail_rail();
}
