// Spacer washers - a row of identical flat ring spacers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 3;    // number of washers in the row
washer_d       = 20;   // outer diameter of a washer (mm)
washer_bore    = 10.5; // diameter of the central hole (mm)
washer_t       = 3;    // thickness of a washer (mm)
washer_gap     = 8;    // centre-to-centre spacing between washers (mm)
eps            = 0.5;  // overcut so cutters pass beyond faces (mm)

$fn = 96;              // smoothness of curved surfaces

// ---------------- Model ----------------
difference() {
    // Solid disc for each washer
    for (i = [0 : washer_count - 1]) {
        translate([(i - (washer_count - 1) / 2) * washer_gap, 0, 0])
            cylinder(d = washer_d, h = washer_t);
    }

    // Central through-hole for each washer
    for (i = [0 : washer_count - 1]) {
        translate([(i - (washer_count - 1) / 2) * washer_gap, 0, -eps])
            cylinder(d = washer_bore, h = washer_t + 2 * eps);
    }
}
