    cylinder(d = washer_d * 2, h = washer_t);

    // Through-holes for each washer, laid out along X with the given gap
    for (i = [0 : washer_count - 1]) {
        x = (i - (washer_count - 1) / 2) * washer_gap;
        translate([x, 0, -eps])
            cylinder(d = washer_bore, h = washer_t + 2 * eps);
