// Spacer washers - a row of identical flat ring spacers that print together.
// Each washer is a separate part and must not touch its neighbours.
// Print orientation: flat on the bed, z = 0 upward.

// ---------------- Parameters ----------------
washer_count   = 3;    // number of washers in the row
washer_od      = 16;   // outer diameter of each washer (mm)
washer_id      = 8.5;  // hole diameter of each washer (mm)
washer_t       = 3;    // thickness of each washer (mm)
washer_gap     = 10;   // centre-to-centre spacing between washers along X (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)
$fn            = 96;   // circle resolution

// ---------------- Model ----------------
difference() {
    // Solid disc for the washers
    cylinder(d = washer_od, h = washer_t);

    // Central hole, cut through with overshoot
    translate([0, 0, -eps])
        cylinder(d = washer_id, h = washer_t + 2 * eps);
}

