    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-groove cutters, running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([x0 + i * groove_pitch, -block_wid / 2 - overcut, block_ht - groove_d])
            rotate([0, 90, 0])
                linear_extrude(height = block_wid + 2 * overcut)
                    polygon([[-groove_wt / 2, 0], [groove_wt / 2, 0],
                              [0, -tan(groove_angle / 2) * groove_d],
                              [0, tan(groove_angle / 2) * groove_d]]);
