// Glass stirring rod rest - block with V-shaped grooves along Y
// Print orientation: flat on bed, grooves facing up

// ---------- Parameters ----------
block_len   = 130;   // block length along X (mm)
block_wid   = 50;    // block width along Y (mm)
block_ht    = 15;    // block height along Z (mm)

groove_n     = 6;    // number of V-grooves
groove_pitch = 20;   // centre-to-centre spacing along X (mm)
groove_wt    = 8;    // groove width at top surface (mm)
groove_d     = 4;    // groove depth from top surface (mm)

eps          = 0.5;  // overcut past faces to avoid coplanar faces (mm)

$fn = 96;

// ---------- Derived ----------
// For a 90-degree V, the two faces are at 45 degrees.
// Extend the cutting shape above the top face by eps*2 so the
// overcut is eps on each side (steeper faces -> less overcut needed).
groove_depth = groove_d + eps * 2;

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running full width along Y, centred along X
    for (i = [0 : groove_n - 1]) {
        x_c = (i - (groove_n - 1) / 2) * groove_pitch;
        translate([x_c, -block_wid / 2 - eps, groove_depth])
            // 90-degree V: two faces at 45 degrees, open along +Z
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-groove_wt / 2, -groove_wt / 2],
                         [groove_wt / 2, -groove_wt / 2],
                         [groove_wt / 2, groove_wt / 2],
                         [-groove_wt / 2, groove_wt / 2]]);
    }
}
