```openscad
// Glass stirring rod rest - block with V-shaped grooves along Y
// Print orientation: flat on bed, grooves facing up

// ---------- Parameters ----------
block_len   = 130;   // block length along X (mm)
block_wid   = 50;    // block width along Y (mm)
block_ht    = 15;    // block height along Z (mm)

groove_n     = 6;    // number of V-grooves
groove_pitch = 20;   // centre-to-centre spacing along X (mm)
groove_wt    = 8;    // groove width at top surface (mm)
groove_d    = 4;     // groove depth from top surface (mm)

eps         = 0.5;   // overcut past faces to avoid coplanar faces (mm)

$fn = 96;

// ---------- Derived ----------
// For a 90-degree V, the side walls are at 45 degrees.
// Extending the V above the top surface by (depth / tan(45)) keeps the
// same cone angle and makes the overcut length equal to the depth.
v_ext      = groove_d / tan(45);   // = groove_d for 90-degree V
x0         = -(groove_n - 1) * groove_pitch / 2;  // first groove centre X
// 2 * sqrt(2) = width of V at a height 2*depth above the tip (top + ext)
top_t      = groove_wt + 2 * sqrt(2) * groove_d;  // cone diameter at cut height

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running full width along Y
    for (i = [0 : groove_n - 1]) {
        translate([x0 + i * groove_pitch - block_len / 2, -block_wid / 2 - eps,
                   block_ht - groove_d])
            linear_extrude(height = block_wid + 2 * eps)
                polygon([[-groove_wt / 2, -v_ext], [groove_wt / 2, -v_ext],
                         [groove_wt / 2, v_ext], [-groove_wt / 2, v_ext]]);
    }
}
