// Hex-nut captive clamping block
// Print orientation: block rests on XY plane at z = 0, builds upward (+Z)

// ---------------- Parameters ----------------
block_x      = 20;    // block length in X (mm)
block_y      = 20;    // block width in Y (mm)
block_z      = 10;    // block height in Z (mm)

nut_d        = 5.5;   // through-hole diameter for hex nut (mm)

hex_af       = 8.2;   // hex pocket size across flats (mm)
hex_depth    = 4.2;   // hex pocket depth from bottom face (mm)

eps          = 0.5;   // cutter overshoot past faces (mm)
$fn          = 96;    // curve resolution

// Derived
hex_r = (hex_af / 2) / cos(30);   // hex circumradius (centre to vertex)

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through-hole, centred on the block
    translate([0, 0, -eps])
        cylinder(d = nut_d, h = block_z + 2 * eps);

    // Hexagonal pocket from bottom face, centred on same axis
    // first vertex on +X, so two flats are parallel to the X axis
    translate([0, 0, block_z - hex_depth])
        cylinder(r = hex_r, h = hex_depth + eps, $fn = 6);
}
