// Split collet for tube grip
// Print orientation: base on bed, slots open upward

// ---- Dimensions (mm) ----
tube_od      = 20;   // outer diameter of tube
bore         = 16;   // bore diameter (through)
height       = 30;   // total height (z = 0 to 30)
slot_width   = 2;    // slot width
slot_depth   = 10;   // slot depth from top end (to z = 20)
slot_count   = 3;    // number of slots
cut_extra    = 0.5;  // overshoot for clean cuts

$fn = 96;

difference() {
    // Main tube body
    cylinder(d = tube_od, h = height);

    // Central bore
    translate([0, 0, -cut_extra])
        cylinder(d = bore, h = height + 2 * cut_extra);

    // Axial slots, evenly spaced, first on +X
    for (i = [0 : slot_count - 1])
        rotate([0, 0, i * 360 / slot_count])
            translate([0, 0, height - slot_depth])
                cube([tube_od / 2 + 1, slot_width, slot_depth + cut_extra]);
}
