// Split collet - a round tube with axial slots that grips a tube when closed
// Print orientation: standing on the bed, slots open at the top end

// ---------------- Parameters ----------------
collet_od      = 20;    // outer diameter of the collet tube
collet_bore    = 16;    // diameter of the bore (tube to be gripped)
collet_length  = 30;    // total length of the collet, z = 0 to z = 30
slot_width     = 2;     // width of each axial slot
slot_depth     = 10;    // slots run from the top end down to z = 20
slot_count     = 3;     // number of slots, evenly spaced
first_slot_ang = 0;     // angle of the first slot, 0 = +X axis
cut_extra      = 0.5;   // overshoot of cutting shapes past faces
$fn            = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Main tube body
    translate([0, 0, 0])
        cylinder(d = collet_od, h = collet_length);

    // Central bore
    translate([0, 0, -cut_extra])
        cylinder(d = collet_bore, h = collet_length + 2 * cut_extra);

    // Axial slots, cut from the top end down to z = slot_depth
    for (i = [0 : slot_count - 1]) {
        a = first_slot_ang + i * 360 / slot_count;
        translate([0, 0, collet_length - slot_depth])
            rotate([0, 0, a])
                translate([0, -1, 0])
                    cube([collet_od / 2 + 1, slot_width, slot_depth + cut_extra]);
    }
}
