x_end = x0 + step_count * step_length;  // end of top step in X (75)
y0 = 0;                       // start of extrusion in Y
y1 = extrusion;               // end of extrusion in Y
z1 = first_height;            // top of first step
z_end = top_height;           // top of last step

// ---------- Model ----------
difference() {
    // Solid block covering the full staircase volume
    translate([x0, y0, 0])
        cube([x_end - x0, extrusion, z_end]);

    // Cut out the empty space under each step, from y = 0 up to the step's top height
    for (i = [0 : step_count - 1]) {
        translate([x0 + i * step_length, y0, 0])
            cube([step_length, extrusion + 2 * overcut, z1 + i * step_height]);
