// Stepped riser - a solid staircase of equal steps, extruded along Y,
// used to set samples at different heights. Print orientation: base on
// the bed (z = 0), steps climbing in +X.
//

// ---------- Parameters ----------
step_count   = 5;     // number of steps
step_length  = 15;    // X length of each step (mm)
step_height  = 10;    // height increase per step (mm)
first_height = 10;    // height of the first step (mm)
extrude_w    = 30;    // Y width of the staircase (mm)
eps          = 0.5;   // cutter overshoot past top faces (mm)

// ---------- Derived ----------
top_height = first_height + step_height * (step_count - 1);  // 50 mm
x0         = 0;
x1         = step_length * step_count;                       // 75 mm

// ---------- Model ----------
difference() {
    // Solid block covering the full X span, from the bed up to the top
    // of the last step.
    translate([x0, 0, 0])
        cube([x1, extrude_w, top_height]);

    // Cut out the "treads": for each step i, remove the region above
    // step i's top face but below the next step's top face (or the top
    // of the part for the last step). This leaves a staircase of solid
    // risers and treads down to the bed.
    for (i = [0 : step_count - 1]) {
        z0 = first_height + step_height * i;
        z1 = z0 + step_height;
        translate([x0 + i * step_length, 0, z0])
            cube([step_length, extrude_w, z1 - z0 + eps]);
    }
}
