// Stepped riser - a solid staircase of equal steps, extruded along Y,
// standing on the bed and climbing in +X. NOVEL general part.
//

// ---- Parameters ----
step_count   = 5;     // number of steps
step_length  = 15;    // X length of each step (mm)
step_height  = 10;    // height gain of each step (mm)
top_height   = 50;    // height of the top step (mm)
top_x        = 75;    // X position of the top step end (mm)
extrusion    = 30;    // Y thickness of the part (mm)
overcut      = 0.5;   // extra length so cutters pass the end face (mm)

// Check: with 5 steps of 15 mm the top step ends at x = 75.
// Check: heights are 10, 20, 30, 40, 50 -> top height 50 mm.

// ---- Model ----
difference() {
    // Solid block of the full staircase profile
    translate([0, 0, 0])
        cube([top_x + overcut, extrusion, top_height]);

    // Cut out the empty space under each step, from the bed up to
    // just below the next step's height. The first step is solid
    // from z = 0 up to z = step_height, so the first cut starts at
    // z = step_height - epsilon.
    for (i = [0 : step_count - 1]) {
        z0 = i * step_height + step_height - overcut;   // floor of cut
        z1 = (i + 1) * step_height - overcut;           // ceiling of cut
        x1 = i * step_length + step_length - overcut;   // start of cut (X)
        x2 = top_x + overcut;                            // end of cut (X)
        translate([x1, 0, z0])
            cube([step_length + overcut, extrusion, z1 - z0]);
    }
}
