step_height  = 10;    // height increase per step (mm)
first_height = 10;    // height of the first step (mm)
extrude_y    = 40;    // Y thickness of the staircase (mm)

// ---- Derived ----
top_height = first_height + step_count * step_height;  // 30 mm
total_x    = step_count * step_length;                 // 45 mm

// ---- Model ----
difference() {
    // Solid block covering the full staircase volume
    translate([-step_length / 2, 0, 0])
        cube([total_x, extrude_y, top_height]);

    // Cut out the "undercut" of each step so they rest on the bed and on the step below.
    // The first step starts at x = 0; subsequent steps start at x = step_length, etc.
    for (i = [0 : step_count - 1]) {
        x0 = i * step_length;
        translate([x0 - 0.01, 0, first_height + i * step_height])
            cube([step_length + 0.01, extrude_y, step_height]);
    }
}
