    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // 45-degree chamfers on the top face, extended past the top and side faces
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([
            sx > 0 ? block_x / 2 - chamfer_w : -block_x / 2 + chamfer_w,
            sy > 0 ? block_y / 2 - chamfer_w : -block_y / 2 + chamfer_w,
            block_h - eps
