chamfer_w    = 4;     // chamfer width (45-degree, along the face diagonal)
top_x        = block_x - 2 * chamfer_w; // top face length in X (72)
top_y        = block_y - 2 * chamfer_w; // top face width in Y (52)
side_h       = block_h - chamfer_w;    // vertical side height (8)

// ---- Modelling parameters ----
eps          = 0.5;   // overshoot for clean boolean cuts
$fn          = 64;

// A 45-degree chamfer along a top edge is an edge running diagonally across the
// top face, parallel to that face. Cutting it with a plane leaves a diagonal
// edge on the top face and stops the adjacent vertical side at z = side_h.
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Chamfer planes for the four top edges
    // Each plane passes through the diagonal edge on the top face and tilts
    // downward, cutting the vertical side after eps mm.
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x / 2 - eps : -block_x / 2,
                   sy > 0 ? block_y / 2 - eps : -block_y / 2,
                   0])
            rotate([0, 0, 45])
                cube([chamfer_w, chamfer_w, side_h + eps]);
    }
}
