    // 45-degree chamfers on the top edges, extended past the top face
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? block_x/2 - eps : -block_x/2,
                   sy > 0 ? block_y/2 - eps : -block_y/2,
                   block_h - eps])
            cube([chamfer_w * cos(chamfer_angle),
                  chamfer_w * cos(chamfer_angle),
                  chamfer_w * sin(chamfer_angle) + eps]);
}
