// Display base with bevelled top edges
// Print orientation: flat on XY plane, top face at z = 12

// ---------- Parameters ----------
block_x      = 100;   // block length in X (mm)
block_y      = 50;    // block width in Y (mm)
block_h      = 12;    // block height in Z (mm)

chamfer_w    = 4;     // chamfer width along the edge (mm)
chamfer_angle = 45;   // chamfer angle relative to the top face (deg)

eps          = 0.5;   // overshoot for clean boolean cuts (mm)
$fn          = 64;    // curve resolution

// ---------- Derived ----------
// Vertical side height after the 45-degree chamfer stops
side_h = block_h - chamfer_w;              // 8 mm
// Top face dimensions (edges trimmed by the chamfers)
top_x  = block_x - 2 * chamfer_w;          // 92 mm
top_y  = block_y - 2 * chamfer_w;          // 42 mm
// Check: at 45 deg the cut loses chamfer_w in X and Y, so the top face is 92 x 42

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Four 45-degree chamfers on the top edges.
    // Each runs for (chamfer_w + eps) along the edge and
    // loses (chamfer_w + eps)/tan(chamfer_angle) in height.
    // At 45 deg the height loss equals the run length.
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? block_x/2 - chamfer_w : -block_x/2,
                   sy > 0 ? block_y/2 - chamfer_w : -block_y/2,
                   0])
            cube([chamfer_w + eps,
                  chamfer_w + eps,
                  (chamfer_w + eps) / tan(chamfer_angle)]);
    }
}
