// Adjustable shim plate with two rounded-end bolt slots
// Print orientation: flat on bed, z = 0 to plate_t

$fn = 64;

// ---- Plate ----
plate_l = 80;     // plate length along X
plate_w = 24;     // plate width along Y
plate_t = 4;      // plate thickness along Z

// ---- Slots ----
slot_w   = 5.5;   // slot width (also end-radius diameter)
slot_len = 12;    // slot overall length, end to end, along X
slot_xs  = [-20, 20]; // slot centre X positions
slot_y   = 0;     // slot centre Y position

// ---- Cut clearance ----
eps = 0.5;        // extension of cutters past faces

// Stadium-shaped slot cutter, centred at (cx, cy)
module slot_cutter(cx, cy) {
    c = slot_len - slot_w;              // centre-to-centre of end radii
    translate([cx, cy, -eps])
        hull() {
            for (dx = [-c/2, c/2])
                translate([dx, 0, 0])
                    cylinder(d = slot_w, h = plate_t + 2*eps);
        }
}

difference() {
    // Plate body
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Through-slots
    for (x = slot_xs)
        slot_cutter(x, slot_y);
}
