// Bench mat for 2 x 60 mm Petri dishes
// Units: mm

plate_x      = 156;    // plate length (X)
plate_y      = 82;     // plate width (Y)
plate_t      = 8;      // plate thickness (Z)

recess_d     = 61.5;   // recess diameter
recess_depth = 2;      // recess depth
recess_n     = 2;      // number of recesses
recess_pitch = 73.5;   // centre-to-centre spacing along X

eps          = 0.5;    // overcut past top face
$fn          = 128;    // circle resolution

difference() {
    // base plate, centred in XY, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // recesses in a single row along X, centred on the plate
    for (i = [0 : recess_n - 1]) {
        x = (i - (recess_n - 1)/2) * recess_pitch;
        translate([x, 0, plate_t - recess_depth])
            cylinder(d = recess_d, h = recess_depth + eps);
    }
}
