// Tube label-writing holding block
// Block with a semicircular channel along X on the top face

// ---- Dimensions (mm) ----
block_len   = 70;   // block length along X
block_wid   = 28;   // block width along Y
block_ht    = 20;   // block height along Z
channel_d   = 12;   // channel diameter (semicircular cross-section)
channel_y   = 0;    // channel axis Y position
channel_z   = 20;   // channel axis Z position (on top surface)
overcut     = 0.5;  // extra length so cuts pass through end faces

$fn = 96;

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular channel: cylinder axis along X at top surface
    // (upper half of the cylinder lies above the block, so the cut is a half-round, 6 mm deep)
    translate([-block_len/2 - overcut, channel_y, channel_z])
        rotate([0, 90, 0])
            cylinder(d = channel_d, h = block_len + 2*overcut);
}
