// DIY syringe pump end block
// Print orientation: block rests on XY plane at z = 0, builds upward (+Z)

// ---------------- Parameters ----------------
block_x      = 44;    // block length along X (mm)
block_y      = 20;    // block depth along Y (mm)
block_z      = 24;    // block height along Z (mm)

bore_d       = 10;    // horizontal bore diameter (through along Y) (mm)
bore_x       = 0;     // bore axis X position (mm)
bore_z       = 12;    // bore axis height (mm)

mount_d      = 4.5;   // vertical mounting hole diameter (mm)
mount_x      = 17;    // mounting hole X offset from centre, used as +/- (mm)
mount_y      = 0;     // mounting hole Y position (mm)

eps          = 0.5;   // cutter overshoot past faces (mm)
$fn          = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Horizontal bore along Y
    translate([bore_x, 0, bore_z])
        rotate([90, 0, 0])
            cylinder(d = bore_d, h = block_y + 2 * eps, center = true);

    // Vertical mounting holes through full height
    for (sx = [-1, 1])
        translate([sx * mount_x, mount_y, -eps])
            cylinder(d = mount_d, h = block_z + 2 * eps);
}
```

