```openscad
// Glassware drying board: base plate with a 3 x 4 grid of vertical pegs

// ---- Base plate ----
plate_x     = 100;   // plate length along X (mm)
plate_y     = 135;   // plate length along Y (mm)
plate_t     = 5;     // plate thickness (mm), z = 0 to 5

// ---- Pegs ----
peg_d       = 8;     // peg diameter (mm)
peg_top_z   = 45;    // peg top height (mm)
peg_h       = peg_top_z - plate_t;  // peg height above plate (40 mm)
peg_nx      = 3;     // number of pegs along X
peg_ny      = 4;     // number of pegs along Y
peg_pitch   = 35;    // centre-to-centre spacing in X and Y (mm)
overlap     = 0.5;   // peg sinks into plate for a solid union (mm)

$fn = 64;            // curve resolution

union() {
    // Base plate, centred in XY
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid, centred on the plate
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([(i - (peg_nx - 1)/2) * peg_pitch,
                       (j - (peg_ny - 1)/2) * peg_pitch,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap);
}
```

