cut_ext  = 0.5;          // extra cut length past faces (mm)

// Derived
slot_r      = slot_w / 2;
slot_centre = slot_len - slot_w;  // distance between end-circle centres

module slot2d() {
    hull() {
        for (s = [-1, 1])
            translate([s * slot_centre / 2, 0])
                circle(r = slot_r, $fn = 64);
    }
}

difference() {
    // Plate body
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Through-slots
    for (x = slot_xs)
        translate([x, slot_y, -cut_ext])
            linear_extrude(height = plate_t + 2 * cut_ext)
                slot2d();
}
