slot_y   = 0;     // slot centre Y position

// ---- Cut clearance ----
eps = 0.5;        // extension of cutters past faces

// Derived
slot_r      = slot_w / 2;               // end radius
slot_cc     = slot_len - slot_w;        // centre-to-centre of end arcs

module slot_cutter() {
    hull() {
        for (s = [-1, 1])
            translate([s * slot_cc / 2, 0, -eps])
                cylinder(r = slot_r, h = plate_t + 2 * eps, $fn = 64);
    }
}

difference() {
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    for (x = slot_xs)
        translate([x, slot_y, 0])
            slot_cutter();
}
