// Magnet carrier disc for rotating sample mixer
// Print orientation: flat on bed, pockets facing up

// ---- Disc ----
disc_d        = 50;    // disc outer diameter
disc_h        = 6;     // disc height

// ---- Magnet pockets ----
pocket_count  = 6;     // number of magnet pockets
pocket_d      = 8.2;   // pocket diameter (magnet + clearance)
pocket_depth  = 4;     // pocket depth from top face
pocket_pcd    = 31.8;  // pitch circle diameter of pocket centres
pocket_start  = 0;     // angle of first pocket (deg, 0 = +X axis)

// ---- Shaft hole ----
shaft_d       = 4;     // motor shaft through-hole diameter

// ---- Misc ----
eps           = 0.5;   // cutter overshoot past faces
$fn           = 96;    // curve resolution

difference() {
    // Main disc body
    cylinder(d = disc_d, h = disc_h);

    // Magnet pockets in top face
    for (i = [0 : pocket_count - 1]) {
        a = pocket_start + i * 360 / pocket_count;
        translate([pocket_pcd / 2 * cos(a), pocket_pcd / 2 * sin(a), disc_h - pocket_depth])
            cylinder(d = pocket_d, h = pocket_depth + eps);
    }

    // Central shaft through-hole
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + 2 * eps);
}
