```openscad
// Wall mounting strip with two countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 64;

// ---- Bar dimensions ----
bar_length    = 50;    // X length of bar
bar_width     = 24;    // Y width of bar
bar_thickness = 6;     // Z thickness of bar

// ---- Screw holes ----
hole_count    = 2;     // number of screw holes
hole_spacing  = 30;    // centre-to-centre distance along X
hole_d        = 4.5;   // through-hole diameter
csk_d         = 9;     // countersink diameter at top surface
csk_angle     = 90;    // countersink included angle (degrees)

// ---- Derived values ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // countersink depth (2.25 mm)
eps       = 0.5;       // overshoot for clean boolean cuts

difference() {
    // Main bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    for (i = [0 : hole_count - 1]) {
        x = -hole_spacing * (hole_count - 1) / 2 + i * hole_spacing;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thickness + 2 * eps);

            // 90-degree countersink, extended eps above top face
            // (radius grows by eps per eps height for 90 degrees)
            translate([0, 0, bar_thickness - csk_depth])
                cylinder(d1 = hole_d,
                         d2 = csk_d + 2 * eps * tan(csk_angle / 2),
                         h  = csk_depth + eps);
        }
    }
}
