// Wall mounting strip with countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 64;

// ---- Bar dimensions ----
bar_length    = 100;   // X length of bar
bar_width     = 20;    // Y width of bar
bar_thickness = 6;     // Z thickness of bar

// ---- Screw holes ----
hole_count    = 3;     // number of screw holes
hole_spacing  = 40;    // centre-to-centre spacing along X
hole_d        = 3.4;   // through-hole diameter
csk_d         = 6.5;   // countersink diameter at top surface
csk_angle     = 90;    // countersink included angle (degrees)

// ---- Derived values ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // countersink depth (1.55 mm at 90 deg)
overcut   = 0.5;                                        // extension of cutters past faces
csk_top_d = csk_d + 2 * overcut * tan(csk_angle / 2);   // cone diameter at overcut height

difference() {
    // Main bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    // Screw holes, centred on the bar along X at y = 0
    for (i = [0 : hole_count - 1]) {
        x = (i - (hole_count - 1) / 2) * hole_spacing;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -overcut])
                cylinder(d = hole_d, h = bar_thickness + 2 * overcut);

            // 90-degree countersink on top face, extended above surface
            translate([0, 0, bar_thickness - csk_depth])
                cylinder(d1 = hole_d, d2 = csk_top_d, h = csk_depth + overcut);
        }
    }
}
