plate_x      = 102;   // plate length (X)
plate_y      = 56;    // plate width (Y)
plate_t      = 8;     // plate thickness (Z)

recess_d     = 36;    // recess diameter
recess_depth = 2;     // recess depth
recess_n     = 2;     // number of recesses
recess_pitch = 46;    // centre-to-centre spacing along X

eps          = 0.5;   // overcut past top face

$fn = 128;

difference() {
    // base plate, centred in XY, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // recesses in a single row along X, centred on the plate
    for (i = [0 : recess_n - 1])
        translate([(i - (recess_n - 1)/2) * recess_pitch, 0, plate_t - recess_depth])
            cylinder(d = recess_d, h = recess_depth + eps, $fn = 128);
}
```

