// Glassware drying board: base plate with a 4x4 grid of vertical pegs

// ---- Base plate ----
plate_x     = 135;   // plate length along X (mm)
plate_y     = 135;   // plate length along Y (mm)
plate_t     = 6;     // plate thickness (mm), z = 0 to 6

// ---- Pegs ----
peg_d       = 6;     // peg diameter (mm)
peg_top_z   = 36;    // top of pegs (mm)
peg_h       = peg_top_z - plate_t;  // peg height above plate (30 mm)
peg_nx      = 4;     // pegs along X
peg_ny      = 4;     // pegs along Y
peg_pitch   = 35;    // centre-to-centre spacing in X and Y (mm)
peg_embed   = 0.5;   // overlap of peg into plate for a solid union (mm)

$fn = 64;            // curve resolution

union() {
    // Base plate, centred in XY, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid, centred on the plate
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([(i - (peg_nx - 1)/2) * peg_pitch,
                       (j - (peg_ny - 1)/2) * peg_pitch,
                       plate_t - peg_embed])
                cylinder(d = peg_d, h = peg_h + peg_embed);
}
