// Adjustable shim plate with two rounded-end bolt slots
// Print orientation: flat on bed, z = 0 to plate_t

$fn = 64;

// ---- Plate ----
plate_l = 50;    // plate length along X (mm)
plate_w = 30;    // plate width along Y (mm)
plate_t = 4;     // plate thickness along Z (mm)

// ---- Slots ----
slot_w   = 4.5;  // slot width (mm) = end radius * 2
slot_len = 12;   // slot overall length, end to end (mm)
slot_xs  = [-14, 14]; // slot centre X positions (mm)
slot_y   = 0;    // slot centre Y position (mm)

// ---- Cut clearance ----
eps = 0.5;       // extension of cutters past faces (mm)

// Derived
slot_r      = slot_w / 2;
slot_centre = slot_len - slot_w; // distance between end-circle centres

module slot_cutter() {
    translate([0, 0, -eps])
        hull() {
            for (s = [-1, 1])
                translate([s * slot_centre / 2, 0, 0])
                    cylinder(r = slot_r, h = plate_t + 2 * eps);
        }
}

difference() {
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    for (x = slot_xs)
        translate([x, slot_y, 0])
            slot_cutter();
}
```

```openscad
// Adjustable shim plate with two rounded-end bolt slots
// Units: mm. Print orientation: flat on bed, z = 0 up to plate_t.

$fn = 64;

// ---- Plate ----
plate_l = 50;     // plate length along X
plate_w = 30;     // plate width along Y
plate_t = 4;      // plate thickness (Z)

// ---- Slots ----
slot_w   = 4.5;   // slot width (also end-radius diameter)
slot_len = 12;    // slot overall length, end to end along X
slot_xs  = [-14, 14]; // slot centre X positions
slot_y   = 0;     // slot centre Y position

// ---- Cutting clearance ----
eps = 0.5;        // extension past faces to avoid coplanar surfaces

// Derived
slot_r      = slot_w / 2;               // end radius
slot_centre = slot_len - slot_w;        // distance between end-circle centres

// Single through-slot cutter (stadium shape), centred at origin in XY
module slot_cutter() {
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            hull() {
                for (s = [-1, 1])
                    translate([s * slot_centre / 2, 0])
