// Microplate riser
// Units: mm. Print orientation: legs down on the bed, top plate at z = 46..50.

// ---------- Parameters ----------
plate_x      = 140;   // top plate length (X)
plate_y      = 90;    // top plate width (Y)
plate_t      = 4;     // top plate thickness
top_z        = 50;    // height of the top face of the plate

leg_size     = 12;    // square leg cross-section (X and Y)

window_x     = 106;   // central window length (X)
window_y     = 46;    // central window width (Y)

eps          = 0.5;   // cutter overshoot past faces
overlap      = 0.01;  // small overlap so legs fuse with the plate

// Derived
plate_bottom_z = top_z - plate_t;   // underside of the plate (= leg height)
leg_h          = plate_bottom_z;

$fn = 64;

// ---------- Model ----------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bottom_z])
            cube([plate_x, plate_y, plate_t]);

        translate([-window_x/2, -window_y/2, plate_bottom_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with the plate's outer edges
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([
            sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
            sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
            0
        ])
            cube([leg_size, leg_size, leg_h + overlap]);
    }
}
