```openscad
// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward (+Z)

// ---------------- Parameters ----------------
block_x      = 88;    // block length along X (mm)
block_y      = 28;    // block width along Y (mm)
block_h      = 25;    // block height along Z (mm)

pocket_w     = 13.2;  // square pocket side (mm)
pocket_depth = 22;    // pocket depth from top face (mm)
pocket_pitch = 20.2;  // centre-to-centre spacing along X (mm)
pocket_count = 4;     // number of pockets

floor_t      = block_h - pocket_depth; // remaining floor thickness = 3 mm
eps          = 0.5;   // overshoot so cutters pass cleanly through the top face

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : pocket_count - 1]) {
        px = (i - (pocket_count - 1) / 2) * pocket_pitch;
        translate([px - pocket_w / 2, -pocket_w / 2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
```

