pocket_pitch = 20.2;  // centre-to-centre spacing along X (mm)
pocket_n     = 5;     // number of pockets

eps          = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 64;

// Derived: floor thickness under pockets = block_h - pocket_depth = 4 mm
// Row start offset so the row is centred on the block
row_start = -(pocket_n - 1) * pocket_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square cuvette pockets, opened from the top face
    for (i = [0 : pocket_n - 1]) {
        translate([row_start + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   block_h - pocket_depth])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
