```openscad
// Hex key organiser block
// Print orientation: base on z = 0, pockets open at the top (+Z)

// ---------------- Parameters ----------------
block_len    = 52;    // block length along X (mm)
block_wid    = 20;    // block width along Y (mm)
block_ht     = 20;    // block height along Z (mm)

pocket_depth = 15;    // depth of each hex pocket from the top face (mm)
pocket_pitch = 10;    // centre-to-centre spacing of pockets along X (mm)
pocket_flats = [2.4, 2.9, 3.4, 4.4]; // across-flats sizes, from -X to +X (mm)

overcut      = 0.5;   // extra length of cutters past the top face (mm)

n_pockets    = len(pocket_flats);

// ---------------- Helpers ----------------
// Hexagonal prism sized by across-flats distance.
// cylinder with $fn=6 puts vertices on the X axis, so two flats are parallel to X.
module hex_prism(flats, h) {
    r = flats / sqrt(3);   // circumradius = flats / (2*cos(30))
    cylinder(r = r, h = h, $fn = 6);
}

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along y = 0, centred on the block
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1) / 2) * pocket_pitch;
        translate([x, 0, block_ht - pocket_depth])
            hex_prism(pocket_flats[i], pocket_depth + overcut);
    }
}
