// Glassware drying board: base plate with a 3x3 grid of vertical pegs

// ---- Base plate ----
plate_x     = 90;   // plate size along X (mm)
plate_y     = 90;   // plate size along Y (mm)
plate_t     = 5;    // plate thickness (mm), z = 0 to 5

// ---- Pegs ----
peg_d       = 10;   // peg diameter (mm)
peg_top_z   = 55;   // peg top height (mm)
peg_h       = peg_top_z - plate_t; // peg height above plate (mm)
peg_pitch   = 30;   // centre-to-centre spacing in X and Y (mm)
peg_nx      = 3;    // pegs along X
peg_ny      = 3;    // pegs along Y
peg_overlap = 0.5;  // peg sinks into plate for a solid union (mm)

$fn = 64;

union() {
    // Base plate centred on origin
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid centred on plate
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([(i - (peg_nx - 1)/2) * peg_pitch,
                       (j - (peg_ny - 1)/2) * peg_pitch,
                       plate_t - peg_overlap])
                cylinder(d = peg_d, h = peg_h + peg_overlap);
}
