plate_y      = 55;    // base plate width along Y (mm)
plate_t      = 5;     // base plate thickness (mm), z = 0 to 5

peg_d        = 8;     // peg diameter (mm)
peg_top_z    = 45;    // peg top height above bed (mm)
peg_h        = peg_top_z - plate_t; // peg height above plate top (40 mm)

peg_nx       = 3;     // number of pegs along X
peg_ny       = 2;     // number of pegs along Y
peg_pitch    = 35;    // centre-to-centre spacing in X and Y (mm)

overlap      = 0.5;   // pegs sink this far into the plate so the union fuses cleanly (mm)

$fn = 64;             // curve resolution

// ---------------- Derived ----------------
grid_x0 = -(peg_nx - 1) * peg_pitch / 2;  // first peg X (-35)
grid_y0 = -(peg_ny - 1) * peg_pitch / 2;  // first peg Y (-17.5)

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([grid_x0 + i * peg_pitch,
                       grid_y0 + j * peg_pitch,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap, $fn = 64);
}
