slot_len = 16;   // slot overall length, end to end (mm)
slot_xs  = [-12, 12]; // slot centre X positions (mm)
slot_y   = 0;    // slot centre Y position (mm)

// ---- Cut clearance ----
eps = 0.5;       // extension of cutters past faces (mm)

// Derived
slot_r      = slot_w / 2;
slot_centre = slot_len - slot_w; // distance between end-circle centres

module slot_cutter() {
    translate([0, 0, -eps])
        hull() {
            for (s = [-1, 1])
                translate([s * slot_centre / 2, 0, 0])
                    cylinder(r = slot_r, h = plate_t + 2 * eps);
        }
}

difference() {
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    for (x = slot_xs)
        translate([x, slot_y, 0])
            slot_cutter();
}
