```openscad
// Wall mounting strip with countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 64;

// ---- Bar dimensions ----
bar_length    = 120;   // X length of bar
bar_width     = 24;    // Y width of bar
bar_thickness = 4;     // Z thickness of bar

// ---- Screw holes ----
hole_count    = 3;     // number of screw holes
hole_spacing  = 50;    // centre-to-centre spacing along X
hole_d        = 4.5;   // through-hole diameter
csk_d         = 9;     // countersink diameter at top surface
csk_angle     = 90;    // countersink included angle (degrees)

// ---- Derived ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // countersink depth (2.25 mm)
eps       = 0.5;       // overshoot for clean boolean cuts

module countersunk_hole() {
    // Through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = bar_thickness + 2 * eps);
    // 90-degree countersink cone, extended eps above top face
    // (radius grows by eps*tan(angle/2) to keep the same cone angle)
    translate([0, 0, bar_thickness - csk_depth])
        cylinder(d1 = hole_d,
                 d2 = csk_d + 2 * eps * tan(csk_angle / 2),
                 h  = csk_depth + eps);
}

difference() {
    // Bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    // Holes along X at y = 0, centred on the bar
    for (i = [0 : hole_count - 1])
        translate([(i - (hole_count - 1) / 2) * hole_spacing, 0, 0])
            countersunk_hole();
}
```

