// Divider insert for sample storage box - open lattice, no floor
// Print orientation: standing on bed, walls build upward (+Z)

// ---------------- Parameters ----------------
outer_x   = 127.5;  // outside length along X (mm)
outer_y   = 96;     // outside width along Y (mm)
height    = 30;     // wall height (mm)
wall      = 1.5;    // thickness of all walls, outer and inner (mm)
cells_x   = 4;      // number of cells along X
cells_y   = 3;      // number of cells along Y
cell      = 30;     // inside size of each square cell (mm)
eps       = 0.5;    // overcut so cutters pass through the top face

// Check: cells_x*cell + (cells_x+1)*wall = 127.5
//        cells_y*cell + (cells_y+1)*wall = 96
pitch = cell + wall;  // centre-to-centre spacing of cells (mm)

// ---------------- Model ----------------
difference() {
    // Solid outer block, centred in XY, resting on z = 0
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Through-cut every cell (no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([-outer_x/2 + wall + i*pitch,
                       -outer_y/2 + wall + j*pitch,
                       -eps])
                cube([cell, cell, height + 2*eps]);
}
