// Horizontal pipette rest
// Print orientation: base plate on the bed (z = 0), uprights build upward (+Z)

$fn = 96;

// ---- Base plate ----
base_len   = 120;   // plate length along X
base_wid   = 40;    // plate width along Y
base_thk   = 4;     // plate thickness (z = 0 to 4)

// ---- Uprights ----
up_thk     = 8;     // upright thickness along X
up_h       = 35;    // upright height (z = 0 to 35)

// ---- Cradle notch ----
notch_r    = 7;     // semicircular notch radius
notch_z    = up_h;  // notch centre height (on top edge)
notch_y    = 0;     // notch centre Y position

eps        = 0.5;   // overcut for clean differences

module upright(x0) {
    difference() {
        translate([x0, -base_wid/2, 0])
            cube([up_thk, base_wid, up_h]);
        // Cradle: cylinder along X, centred on top edge
        translate([x0 - eps, notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // Base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // Uprights at each end, flush with plate ends
    for (x0 = [-base_len/2, base_len/2 - up_thk])
        upright(x0);
}
