n_pockets    = len(pocket_flats);              // number of pockets

// ---- Cutting overlap ----
eps = 0.5;           // extension past the top face to avoid coplanar faces (mm)

// Circumradius of a hexagon from its across-flats size
function hex_r(f) = f / sqrt(3);

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along y = 0, centred on the block
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1) / 2) * pocket_pitch;
        // $fn = 6 places vertices on the X axis, so two flats are parallel to X
        translate([x, 0, block_ht - pocket_depth])
            cylinder(r = hex_r(pocket_flats[i]),
                     h = pocket_depth + eps,
                     $fn = 6);
    }
}
