// Units: mm. Prints flat on the bed (z = 0 upward), centred on origin.

// ---------- Parameters ----------
ring_thickness   = 4;     // ring height (Z)
outer_diameter   = 60;    // outer diameter of annulus
inner_diameter   = 32;    // inner (bore) diameter of annulus
hole_count       = 8;     // number of mounting through-holes
hole_diameter    = 5.5;   // through-hole diameter
hole_pcd         = 46;    // pitch circle diameter of holes
hole_start_angle = 0;     // first hole on +X axis (degrees)
cut_overlap      = 0.5;   // extra length on cutters past each face

$fn = 128;                // smoothness of curved shapes

// ---------- Model ----------
difference() {
    // Solid disc
    cylinder(h = ring_thickness, d = outer_diameter);

    // Central bore
    translate([0, 0, -cut_overlap])
        cylinder(h = ring_thickness + 2 * cut_overlap, d = inner_diameter);

    // Evenly spaced through-holes on the pitch circle
    for (i = [0 : hole_count - 1]) {
        a = hole_start_angle + i * 360 / hole_count;
        translate([hole_pcd / 2 * cos(a), hole_pcd / 2 * sin(a), -cut_overlap])
            cylinder(h = ring_thickness + 2 * cut_overlap, d = hole_diameter, $fn = 64);
    }
}
```

