```openscad
// Diffuser sheet frame for lab light pad
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// --- Dimensions (mm) ---
frame_x      = 140;   // outer size in X
frame_y      = 110;   // outer size in Y
frame_t      = 5;     // frame thickness (Z)
window_x     = 124;   // window size in X
window_y     = 94;    // window size in Y
hole_d       = 3.4;   // corner through-hole diameter
hole_x       = 66;    // hole centre offset from origin in X (±)
hole_y       = 51;    // hole centre offset from origin in Y (±)
eps          = 0.5;   // cutter overshoot past faces

difference() {
    // Outer plate
    translate([-frame_x/2, -frame_y/2, 0])
        cube([frame_x, frame_y, frame_t]);

    // Central window
    translate([-window_x/2, -window_y/2, -eps])
        cube([window_x, window_y, frame_t + 2*eps]);

    // Corner through-holes
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx*hole_x, sy*hole_y, -eps])
            cylinder(d = hole_d, h = frame_t + 2*eps);
}
```

