```openscad
// Magnet carrier disc for rotating sample mixer
// Print orientation: flat on bed, magnet pockets facing up

// ---------- Parameters ----------
disc_d        = 50;    // disc outer diameter
disc_h        = 8;     // disc height
pocket_d      = 10.2;  // magnet pocket diameter
pocket_depth  = 3;     // magnet pocket depth from top face
pocket_count  = 4;     // number of magnet pockets
pocket_pcd    = 29.8;  // pitch circle diameter of pocket centres
shaft_d       = 6;     // central motor shaft hole diameter
eps           = 0.5;   // overcut for clean boolean differences

$fn = 96;

// ---------- Model ----------
difference() {
    // Main disc
    cylinder(d = disc_d, h = disc_h);

    // Magnet pockets in top face, first on +X axis
    for (i = [0 : pocket_count - 1])
        rotate([0, 0, i * 360 / pocket_count])
            translate([pocket_pcd / 2, 0, disc_h - pocket_depth])
                cylinder(d = pocket_d, h = pocket_depth + eps);

    // Central through hole for motor shaft
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + 2 * eps);
}
```

