module countersunk_hole() {
    // Through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = bar_thickness + 2 * eps);
    // 90-degree countersink cone, extended eps above the top face
    // (radius grows by eps*tan(angle/2) to keep the same cone angle)
    translate([0, 0, bar_thickness - csk_depth])
        cylinder(d1 = hole_d,
                 d2 = csk_d + 2 * eps * tan(csk_angle / 2),
                 h  = csk_depth + eps);
}

difference() {
    // Bar, centred in X and Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    // Screw holes along X at y = 0, centred on the bar
    for (i = [0 : hole_count - 1])
        translate([(i - (hole_count - 1) / 2) * hole_spacing, 0, 0])
            countersunk_hole();
}
