```openscad
// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward (+Z)

// ---------------- Parameters ----------------
block_x      = 90;    // block length along X (mm)
block_y      = 30;    // block width along Y (mm)
block_h      = 25;    // block height along Z (mm)

pocket_w     = 13;    // square pocket side (mm)
pocket_depth = 21;    // pocket depth from top face (mm)
pocket_pitch = 20;    // centre-to-centre spacing along X (mm)
pocket_count = 4;     // number of pockets

eps          = 0.5;   // overshoot of cutters past the top face (mm)

$fn = 64;

// Floor thickness under pockets (= 25 - 21 = 4 mm)
floor_t = block_h - pocket_depth;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : pocket_count - 1]) {
        px = (i - (pocket_count - 1) / 2) * pocket_pitch;
        translate([px - pocket_w / 2, -pocket_w / 2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
```

```openscad
// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward (+Z)

// ---------------- Parameters ----------------
block_x      = 90;    // block length along X (mm)
block_y      = 30;    // block width along Y (mm)
block_h      = 25;    // block height along Z (mm)

pocket_w     = 13;    // square pocket side (mm)
pocket_depth = 21;    // pocket depth from top face (mm)
pocket_pitch = 20;    // centre-to-centre spacing along X (mm)
pocket_n     = 4;     // number of pockets

eps          = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 64;

// Derived: floor thickness under pockets = block_h - pocket_depth = 4 mm
floor_t = block_h - pocket_depth;

// X position of the first pocket so the row is centred on the block
row_start_x = -(pocket_n - 1) * pocket_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square cuvette pockets, opened from the top face
    for (i = [0 : pocket_n - 1]) {
        translate([row_start_x + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
