// Tube label-writing holding block
// Block with a semicircular channel along X on the top face

// ---------- Parameters ----------
block_len   = 70;    // block length along X (mm)
block_wid   = 28;    // block width along Y (mm)
block_ht    = 18;    // block height along Z (mm)

chan_dia    = 15;    // channel diameter (mm)
chan_r      = chan_dia / 2;  // channel radius -> 7.5 mm deep
chan_y      = 0;     // channel axis Y position (mm)
chan_z      = block_ht;      // channel axis Z position, on top surface (mm)

overcut     = 0.5;   // extra length so cutter passes beyond end faces (mm)

$fn = 128;           // curve resolution

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

