```openscad
// Flat spacer ring - raises an instrument off the bench
// Print orientation: flat on the bed, building up in +Z

// ---------- Dimensions (mm) ----------
ring_thickness   = 6;     // ring height (Z)
outer_diameter   = 100;   // outer diameter of annulus
inner_diameter   = 80;    // inner diameter of annulus
hole_diameter    = 5.5;   // through-hole diameter
hole_pcd         = 90;    // pitch circle diameter of holes
hole_count       = 3;     // number of evenly spaced holes
hole_start_angle = 0;     // first hole on +X axis (degrees)

// ---------- Modelling parameters ----------
cut_overlap = 0.5;        // cutters extend past faces to avoid coplanar faces
$fn = 128;                // facet count for curved surfaces

// ---------- Model ----------
difference() {
    // Solid disc
    cylinder(h = ring_thickness, d = outer_diameter);

    // Central bore
    translate([0, 0, -cut_overlap])
        cylinder(h = ring_thickness + 2 * cut_overlap, d = inner_diameter);

    // Through-holes on pitch circle
    for (i = [0 : hole_count - 1]) {
        a = hole_start_angle + i * 360 / hole_count;
        translate([hole_pcd / 2 * cos(a), hole_pcd / 2 * sin(a), -cut_overlap])
            cylinder(h = ring_thickness + 2 * cut_overlap, d = hole_diameter, $fn = 64);
    }
}
```

