```openscad
// Glassware drying board: base plate with a 3 x 2 grid of vertical pegs
// Print orientation: base plate flat on the bed, pegs pointing up (+Z)

// ---------------- Parameters ----------------
plate_x      = 100;   // base plate length along X (mm)
plate_y      = 60;    // base plate width along Y (mm)
plate_t      = 4;     // base plate thickness (mm), z = 0 to 4

peg_d        = 10;    // peg diameter (mm)
peg_top_z    = 34;    // peg top height above the bed (mm)
peg_h        = peg_top_z - plate_t;  // peg height above the plate top (30 mm)

peg_nx       = 3;     // number of pegs along X
peg_ny       = 2;     // number of pegs along Y
peg_pitch    = 40;    // centre-to-centre peg spacing, both directions (mm)

overlap      = 0.01;  // small overlap so pegs fuse into the plate

$fn = 64;             // curve resolution

