// Units: mm. Print orientation: flat on bed, z = 0 up to plate_t.

$fn = 64;

// ---- Plate ----
plate_l = 60;     // plate length along X
plate_w = 20;     // plate width along Y
plate_t = 4;      // plate thickness (Z)

// ---- Slots ----
slot_w     = 5.5;          // slot width (also end-radius diameter)
slot_len   = 16;           // slot overall length, end to end
slot_x     = [-17, 17];    // slot centre X positions
slot_y     = 0;            // slot centre Y position
slot_r     = slot_w / 2;   // end radius
slot_centre_span = slot_len - slot_w;  // distance between end-circle centres

// ---- Cut clearance ----
eps = 0.5;       // extension of cutters past faces

module slot_cutter() {
    // Stadium-shaped slot running along X, extended through the plate
    translate([0, 0, -eps])
        hull() {
            for (sx = [-slot_centre_span / 2, slot_centre_span / 2])
                translate([sx, 0, 0])
                    cylinder(r = slot_r, h = plate_t + 2 * eps, $fn = 64);
        }
}

difference() {
    // Plate body, centred in X/Y, resting on z = 0
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Through-slots
    for (x = slot_x)
        translate([x, slot_y, 0])
            slot_cutter();
}
