```openscad
// Wall mounting strip with countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 64;

// ---- Bar dimensions ----
bar_length    = 190;   // X length of bar
bar_width     = 24;    // Y width of bar
bar_thickness = 6;     // Z thickness of bar

// ---- Screw holes ----
hole_count    = 5;     // number of screw holes
hole_pitch    = 40;    // spacing between hole centres along X
hole_d        = 4.5;   // through-hole diameter
csk_d         = 9;     // countersink diameter at top surface
csk_angle     = 90;    // countersink included angle (degrees)

// ---- Derived values ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // countersink depth (2.25 mm)
eps       = 0.5;                                        // overshoot for clean cuts
csk_top_d = csk_d + 2 * eps * tan(csk_angle / 2);       // cone diameter at overshoot height
first_x   = -(hole_count - 1) * hole_pitch / 2;         // X of first hole (-80)

difference() {
    // Main bar
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    // Screw holes with countersinks
    for (i = [0 : hole_count - 1]) {
        translate([first_x + i * hole_pitch, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thickness + 2 * eps);

            // 90-degree countersink, extended past the top face
            translate([0, 0, bar_thickness - csk_depth])
                cylinder(d1 = hole_d, d2 = csk_top_d, h = csk_depth + eps);
        }
    }
}
```

