hole_count   = 3;     // number of screw holes
hole_pitch   = 30;    // centre-to-centre hole spacing along X (mm)
hole_d       = 4.5;   // through-hole diameter (mm)

csk_d        = 9;     // countersink diameter at top surface (mm)
csk_angle    = 90;    // countersink included angle (degrees)

eps          = 0.5;   // overshoot for clean boolean cuts (mm)
$fn          = 96;    // curve resolution

// ---------- Derived values ----------
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2);  // = 2.25 mm for 90 deg
csk_d_ext = csk_d + 2 * eps * tan(csk_angle / 2);       // cone diameter at z = thick + eps
first_x   = -(hole_count - 1) * hole_pitch / 2;         // X of first hole (-30)

// ---------- Model ----------
difference() {
    // Flat bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    for (i = [0 : hole_count - 1]) {
        translate([first_x + i * hole_pitch, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(h = bar_thick + 2 * eps, d = hole_d);

            // 90-degree countersink on top face
            translate([0, 0, bar_thick - csk_depth])
                cylinder(h = csk_depth + eps, d1 = hole_d, d2 = csk_d_ext);
        }
    }
}
