// Tubing organiser - flat plate with notches along +Y edge
// Units: mm

plate_len   = 70;   // plate length (X)
plate_wid   = 24;   // plate width (Y)
plate_thk   = 4;    // plate thickness (Z)

notch_count = 6;    // number of notches
