// Bench mat for 3 Petri dishes (60 mm) - anti-slide recesses
// Print orientation: flat on bed, recesses facing up

// ---- Plate ----
plate_x = 226;      // plate length along X (mm)
plate_y = 82;       // plate width along Y (mm)
plate_t = 8;        // plate thickness (mm)

// ---- Recesses ----
recess_d     = 61.5;  // recess diameter (mm)
recess_depth = 4;     // recess depth from top face (mm)
recess_n     = 3;     // number of recesses
recess_pitch = 71.5;  // centre-to-centre spacing along X (mm)

// ---- Misc ----
eps = 0.5;          // overcut past faces to avoid coplanar surfaces
$fn = 128;          // circle resolution

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Row of circular recesses, centred on the plate
    for (i = [0 : recess_n - 1]) {
        x = (i - (recess_n - 1)/2) * recess_pitch;
        translate([x, 0, plate_t - recess_depth])
            cylinder(d = recess_d, h = recess_depth + eps);
    }
}
