```openscad
// Hex key organiser block
// Print orientation: base on z = 0, pockets open at the top

// ---- Block dimensions ----
block_len   = 74;    // block length along X (mm)
block_wid   = 18;    // block width along Y (mm)
block_ht    = 25;    // block height along Z (mm)

// ---- Pocket parameters ----
pocket_depth = 15;                    // pocket depth from top face (mm)
pocket_pitch = 10;                    // centre-to-centre spacing along X (mm)
pocket_flats = [2.4, 2.9, 3.4, 4.4, 5.4, 6.4]; // across-flats sizes, -X to +X (mm)
pocket_count = len(pocket_flats);     // number of pockets
overcut      = 0.5;                   // extension past the top face for a clean cut (mm)

// Hexagon circumradius from across-flats size
function hex_r(af) = af / sqrt(3);

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along y = 0, centred on the block
    for (i = [0 : pocket_count - 1]) {
        x = (i - (pocket_count - 1) / 2) * pocket_pitch;
        // $fn = 6 places vertices on the X axis, so two flats are parallel to X
        translate([x, 0, block_ht - pocket_depth])
            cylinder(r = hex_r(pocket_flats[i]),
                     h = pocket_depth + overcut,
                     $fn = 6);
    }
}
```

