```openscad
// Wall mounting strip with two countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 64;

// ---- Bar dimensions ----
bar_length = 74;    // X length of bar
bar_width  = 16;    // Y width of bar
bar_thick  = 4;     // Z thickness of bar

// ---- Screw holes ----
hole_count   = 2;     // number of screw holes
hole_spacing = 50;    // centre-to-centre distance along X
hole_d       = 5.5;   // through-hole diameter
csk_d        = 11;    // countersink diameter at top surface
csk_angle    = 90;    // countersink included angle (degrees)

// ---- Derived ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // depth of cone
eps       = 0.5;     // overshoot for clean boolean cuts

difference() {
    // Main bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    // Screw holes, centred on the bar along X at y = 0
    for (i = [0 : hole_count - 1]) {
        x = -hole_spacing * (hole_count - 1) / 2 + i * hole_spacing;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thick + 2 * eps);

            // 90-degree countersink, extended eps above top face
            translate([0, 0, bar_thick - csk_depth])
                cylinder(d1 = hole_d,
                         d2 = csk_d + 2 * eps * tan(csk_angle / 2),
                         h  = csk_depth + eps);
        }
    }
}
