// Divider insert for sample storage box - open lattice, no floor
// Print orientation: standing on bed, walls build upward (+Z)

// ---------------- Parameters ----------------
outer_x   = 132.2;  // outside length along X (mm)
outer_y   = 106;    // outside width along Y (mm)
height    = 20;     // wall height (mm)
wall      = 1.2;    // thickness of all walls, outer and inner (mm)
cells_x   = 5;      // number of cells along X
cells_y   = 4;      // number of cells along Y
cell      = 25;     // inside size of each square cell (mm)
eps       = 0.5;    // overcut for clean boolean differences (mm)

// Check: cells_x*cell + (cells_x+1)*wall = 132.2
//        cells_y*cell + (cells_y+1)*wall = 106
pitch = cell + wall;  // centre-to-centre spacing of cells (mm)

// ---------------- Model ----------------
difference() {
    // Solid outer block, centred in XY, sitting on z = 0
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Cut out each open cell (through, no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([-outer_x/2 + wall + i*pitch,
                       -outer_y/2 + wall + j*pitch,
                       -eps])
                cube([cell, cell, height + 2*eps]);
}
