```openscad
// Tubing reel - printed lying on bottom flange
$fn = 128;

flange_d   = 70;   // flange diameter
flange_t   = 2;    // flange thickness
core_d     = 25;   // core diameter
core_h     = 25;   // core height (z = 2 to z = 27)
bore_d     = 10;   // central bore diameter
eps        = 0.5;  // cut overlap

total_h = flange_t + core_h + flange_t; // 29 mm

difference() {
    union() {
        // bottom flange
        cylinder(d = flange_d, h = flange_t);
        // core (slightly overlapping flanges for a clean union)
        translate([0, 0, flange_t - 0.01])
            cylinder(d = core_d, h = core_h + 0.02);
        // top flange
        translate([0, 0, flange_t + core_h])
            cylinder(d = flange_d, h = flange_t);
    }
    // central bore
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
```

