// Pipe saddle clamp - a block with a semicircular groove that cradles a round pipe or
// rod against a flat surface, with a bolt hole each side to screw it down. NOVEL part.
//

pipe_d = 9.8;
bolt_d = 6.7;
base_t = 5.6;

