    translate([0, -L / 2 - 1, h]) rotate([-90, 0, 0]) cylinder(h = L + 2, r = sr);   // groove
    for (x = [-(pipe_d / 2 + margin / 2), pipe_d / 2 + margin / 2])
        translate([x, 0, -1]) cylinder(h = h + 2, d = bolt_d);                        // bolt holes
}
