                translate([pitch_r, 0, 0])
                    linear_extrude(thick)
                        polygon([[-1.5 * mod, -tw / 2], [-1.5 * mod, tw / 2],
                                 [mod, tw / 3],          [mod, -tw / 3]]);
    }
    translate([0, 0, -1]) cylinder(h = thick + 2, d = bore);
}
