            linear_extrude(wide) polygon([[t - ov, t - ov], [g, t - ov], [t - ov, g]]);   // diagonal brace
    }
    translate([arm * 0.72, wide / 2, -1]) cylinder(h = t + 2, d = screw);
    translate([-1, wide / 2, arm * 0.72]) rotate([0, 90, 0]) cylinder(h = t + 2, d = screw);
}
